// The ledger mod's review findings as the pane's review comments, so each
// shows on its line the way a request's thread does. Lens works without the
// ledger: with no run there are none.

import type { LedgerRunSeen } from '../types/ledger'
import type { Comment } from './review'

const PREFIX = 'ledger-'

// Whether a comment is a ledger finding: it has no thread on a forge to answer
// or resolve.
export const isFinding = (comment: Comment): boolean => comment.id.startsWith(PREFIX)

// A path with its `.` and `..` parts folded.
const folded = (path: string): string => {
  const parts: string[] = []

  for (const part of path.split('/')) {
    if (part === '..') {
      parts.pop()
    } else if (part !== '.' && part !== '') {
      parts.push(part)
    }
  }

  return `${path.startsWith('/') ? '/' : ''}${parts.join('/')}`
}

// A path another mod names, made absolute: as it is when it starts at the
// root, else from `root`, the session's folder.
export const placeOf = (path: string, root: string): string =>
  folded(path.startsWith('/') ? path : `${root}/${path}`)

// Where a finding's file is under the folder being reviewed, or undefined when
// it is not there. An agent writes the path from the session's folder, which
// may be the folder under review, one above it, or one inside it; failing
// those, a changed file whose path ends with the finding's is the one meant.
const placed = (path: string, repo: string, root: string, files: readonly string[]): string | undefined => {
  const full = folded(path.startsWith('/') ? path : `${root}/${path}`)

  if (full.startsWith(`${repo}/`)) {
    return full.slice(repo.length + 1)
  }

  const tail = folded(path).replace(/^\//, '')

  return files.find(one => one === tail || one.endsWith(`/${tail}`) || tail.endsWith(`/${one}`))
}

// The run's findings as comments on the files of `repo`, the folder under
// review. `root` is the session's folder and `files` the changed files' paths.
// A fixed finding is a resolved thread; one with no line is on the file as a
// whole.
export const findingComments = (
  run: LedgerRunSeen | null | undefined,
  repo: string,
  root: string,
  files: readonly string[],
): Comment[] =>
  (run?.findings ?? []).flatMap(one => {
    const path = placed(one.path, repo, root, files)

    return path === undefined
      ? []
      : [
          {
            id: `${PREFIX}${one.id}`,
            path,
            line: one.line ?? 0,
            author: `ledger ${one.severity}${one.task === undefined ? '' : ` · ${one.task}`}`,
            body: one.summary,
            when: new Date(one.at).toISOString(),
            ...(one.status === 'fixed' ? { isResolved: true } : {}),
          },
        ]
  })

files.hooks/review.ts:
// Pull request / merge request lookup: turns what the user typed into two refs that exist locally.
// Handle-free on purpose: every command goes through the `run` the caller passes in.

export type Run = (
  argv: string[],
  timeoutMs?: number,
) => Promise<{ exitCode: number; stdout: string; stderr: string }>

export type Forge = 'github' | 'gitlab' | 'unknown'

export type Request = {
  host: Forge
  number: number
  // "owner/repo" (or "group/sub/repo") when the text was a URL, so a link to another repo can be refused.
  repo?: string
}

export type Resolved = {
  side: string // the private ref holding the request's head, e.g. refs/lens/pr-12
  against: string // commit hash the head is compared with: where the branch forked from its target
  title: string // the request's title, or a note that the target was guessed
  label: string // "PR #12" or "MR !34"
  target: string // the target branch name, e.g. "main"
  isTargetGuessed: boolean // true when the forge CLI could not be asked
}

const FETCH_MS = 120_000
const CLI_MS = 30_000
const LOCAL_MS = 10_000

const REF_ROOT = 'refs/lens'

const asNumber = (digits: string | undefined): number | undefined => {
  const value = Number(digits)

  return Number.isSafeInteger(value) && value > 0 ? value : undefined
}

const trimRepo = (path: string): string => path.replace(/^\/+|\/+$/g, '').replace(/\.git$/i, '')

export const parseRequest = (text: string): Request | undefined => {
  const typed = text.trim()

  const mergeRequest = /^(?:https?:\/\/)?[^/\s]+\/(\S+?)\/(?:-\/)?merge_requests\/(\d+)(?:[/?#]\S*)?$/i.exec(typed)
  const pull = /^(?:https?:\/\/)?[^/\s]+\/(\S+?)\/pull\/(\d+)(?:[/?#]\S*)?$/i.exec(typed)
  const linked = mergeRequest ?? pull

  if (linked) {
    const number = asNumber(linked[2])

    return number === undefined
      ? undefined
      : { host: mergeRequest ? 'gitlab' : 'github', number, repo: trimRepo(linked[1] ?? '') }
  }

  const short = /^(pr|pull|mr)?\s*([#!])?\s*(\d+)$/i.exec(typed)

  if (!short) {
    return undefined
  }

  const number = asNumber(short[3])
  const word = short[1]?.toLowerCase()

  if (number === undefined) {
    return undefined
  }

  if (word !== undefined) {
    return { host: word === 'mr' ? 'gitlab' : 'github', number }
  }

  // "!34" is GitLab's own notation. "#12" is used loosely for both, so it is not a hint.
  return { host: short[2] === '!' ? 'gitlab' : 'unknown', number }
}

// Host and "owner/repo" path of a git remote URL, in its https, ssh:// or scp-like (git@host:path) form.
export const remoteParts = (remoteUrl: string): { host: string; repo: string } | undefined => {
  const url = remoteUrl.trim()
  const withScheme = /^[a-z][a-z0-9+.-]*:\/\/(?:[^@/\s]+@)?([^/:\s]+)(?::\d+)?\/(\S+)$/i.exec(url)
  const scpLike = /^(?:[^@/\s]+@)?([^/:\s]+):(?!\/\/)(\S+)$/.exec(url)
  const found = withScheme ?? scpLike

  if (!found) {
    return undefined
  }

  return { host: (found[1] ?? '').toLowerCase(), repo: trimRepo(found[2] ?? '') }
}

export const forgeOf = (remoteUrl: string): Forge => {
  const host = remoteParts(remoteUrl)?.host ?? ''

  if (host.includes('github')) {
    return 'github'
  }

  return host.includes('gitlab') ? 'gitlab' : 'unknown'
}

const lastLine = (text: string): string =>
  text
    .split('\n')
    .map(line => line.trim())
    .filter(line => line !== '')
    .at(-1) ?? ''

const text = (value: unknown): string => (typeof value === 'string' ? value.trim() : '')

type Viewed = { title: string; target: string; forkPoint: string } | { why: string }

// Why the forge CLI gave nothing, in words that fit after "target guessed as main: ".
const whyNot = (cli: string, ran: { exitCode: number; stderr: string }): string => {
  if (/timed? ?out/i.test(ran.stderr)) {
    return `${cli} did not answer`
  }

  if (
    ran.exitCode === -1 ||
    ran.exitCode === 127 ||
    /ENOENT|command not found|no such file|not found in \$?PATH/i.test(ran.stderr)
  ) {
    return `${cli} is not installed`
  }

  if (/auth login|logged in|authenticat|unauthorized|401|token/i.test(ran.stderr)) {
    return `${cli} is not signed in, run ${cli} auth login`
  }

  return `${cli} could not read it`
}

const view = async (run: Run, forge: 'github' | 'gitlab', number: number, slug: string | undefined): Promise<Viewed> => {
  const cli = forge === 'github' ? 'gh' : 'glab'

  // gh is pointed at origin explicitly: on its own it may pick another remote (a fork's upstream).
  const argv =
    forge === 'github'
      ? [
          'gh',
          'pr',
          'view',
          String(number),
          ...(slug === undefined ? [] : ['--repo', slug]),
          '--json',
          'number,title,baseRefName,headRefName,baseRefOid',
        ]
      : ['glab', 'mr', 'view', String(number), '--output', 'json']

  const ran = await run(argv, CLI_MS).catch((error: unknown) => ({ exitCode: -1, stdout: '', stderr: String(error) }))

  if (ran.exitCode !== 0) {
    return { why: whyNot(cli, ran) }
  }

  try {
    const parsed = JSON.parse(ran.stdout) as Record<string, unknown>
    const refs = (parsed.diff_refs ?? {}) as Record<string, unknown>
    const target = text(forge === 'github' ? parsed.baseRefName : parsed.target_branch)

    if (target === '') {
      return { why: `${cli} did not name a target branch` }
    }

    return {
      title: text(parsed.title),
      target,
      forkPoint: text(forge === 'github' ? parsed.baseRefOid : refs.base_sha),
    }
  } catch {
    return { why: `${cli} gave an answer that could not be read` }
  }
}

export const resolveRequest = async (run: Run, typed: string): Promise<Resolved | { error: string }> => {
  const request = parseRequest(typed)

  if (!request) {
    return { error: `"${typed.trim()}" is not a PR or MR: type a number like 12, or paste its URL` }
  }

  const remote = await run(['git', 'remote', 'get-url', 'origin'], LOCAL_MS)

  if (remote.exitCode !== 0 || remote.stdout.trim() === '') {
    return { error: 'This repo has no remote named origin to fetch a PR or MR from' }
  }

  const origin = remoteParts(remote.stdout)
  const known = forgeOf(remote.stdout)
  const forge = known === 'unknown' ? request.host : known

  if (forge === 'unknown') {
    return {
      error: `This repo's origin is not GitHub or GitLab; type "pr ${request.number}" or "mr ${request.number}" to say which it is`,
    }
  }

  const label = forge === 'github' ? `PR #${request.number}` : `MR !${request.number}`

  if (request.repo !== undefined && origin && request.repo.toLowerCase() !== origin.repo.toLowerCase()) {
    return { error: `That link is for ${request.repo}, but this repo's origin is ${origin.repo}; open that repo instead` }
  }

  const side = `${REF_ROOT}/${forge === 'github' ? 'pr' : 'mr'}-${request.number}`
  const tip = `${side}-base`
  const remoteHead = `refs/${forge === 'github' ? 'pull' : 'merge-requests'}/${request.number}/head`

  // The leading + lets a later fetch move the private ref after a force-push. No local branch is touched.
  const [fetched, viewed] = await Promise.all([
    run(['git', 'fetch', '--no-tags', 'origin', `+${remoteHead}:${side}`], FETCH_MS),
    view(run, forge, request.number, origin ? `${origin.host}/${origin.repo}` : undefined),
  ])

  if (fetched.exitCode !== 0) {
    return {
      error: /couldn't find remote ref/i.test(fetched.stderr)
        ? `${label} was not found on origin`
        : `${label} could not be fetched from origin: ${lastLine(fetched.stderr) || 'git fetch failed'}`,
    }
  }

  const fetchTarget = async (branch: string) =>
    run(['git', 'fetch', '--no-tags', 'origin', `+refs/heads/${branch}:${tip}`], FETCH_MS)

  let target = ''

  if ('why' in viewed) {
    const pointed = await run(['git', 'symbolic-ref', '--short', 'refs/remotes/origin/HEAD'], LOCAL_MS)
    const named = pointed.exitCode === 0 ? pointed.stdout.trim().replace(/^origin\//, '') : ''

    for (const branch of [...new Set([named, 'main', 'master'])].filter(one => one !== '')) {
      if ((await fetchTarget(branch)).exitCode === 0) {
        target = branch
        break
      }
    }

    if (target === '') {
      return { error: `No target branch for ${label} could be found on origin (${viewed.why})` }
    }
  } else {
    const got = await fetchTarget(viewed.target)

    if (got.exitCode !== 0) {
      return {
        error: `The target branch ${viewed.target} of ${label} could not be fetched from origin: ${lastLine(got.stderr) || 'git fetch failed'}`,
      }
    }

    target = viewed.target
  }

  // The forge records the target's commit the request is measured from. Once a request is merged, its
  // head is inside the target, so the target's tip alone would give an empty comparison.
  const forkPoint = 'why' in viewed ? '' : viewed.forkPoint
  const hasForkPoint =
    forkPoint !== '' && (await run(['git', 'cat-file', '-e', `${forkPoint}^{commit}`], LOCAL_MS)).exitCode === 0

  const merged = await run(['git', 'merge-base', side, hasForkPoint ? forkPoint : tip], LOCAL_MS)
  const against = merged.stdout.trim()

  if (merged.exitCode !== 0 || against === '') {
    return {
      error: `${label} and ${target} share no history here; if this is a shallow clone, run git fetch --unshallow`,
    }
  }

  const head = await run(['git', 'rev-parse', side], LOCAL_MS)
  const isEmpty = head.stdout.trim() === against

  const notes = [
    ...('why' in viewed ? [`target guessed as ${target}: ${viewed.why}`] : []),
    ...(isEmpty ? [`already merged into ${target}, nothing left to compare`] : []),
  ]

  const name = 'why' in viewed ? '' : viewed.title

  return {
    side,
    against,
    title: [name, notes.length > 0 ? `(${notes.join('; ')})` : ''].filter(part => part !== '').join(' ') || label,
    label,
    target,
    isTargetGuessed: 'why' in viewed,
  }
}

// ---------------------------------------------------------------------------------------------
// Review comments: reading every comment on a request, and posting one on a line.
// ---------------------------------------------------------------------------------------------

export type Comment = {
  // Line comments carry the forge's own number ("4109147516"). On GitHub the general ones are
  // prefixed ("issue-5917169258", "review-5393240365"), because the three kinds are numbered apart.
  id: string
  // Where it is attached: a path relative to the REPO ROOT and a 1-based line in the request's
  // head version of the file. `line` is 0 for a comment on the file as a whole, one on a removed
  // line (see oldLine), or one whose line no longer exists (outdated). `path` is '' for a general
  // comment on the request.
  path: string
  line: number
  author: string
  body: string
  when: string // ISO time as the forge gives it
  replyTo?: string // the id of the comment it answers: always the first comment of its thread
  isResolved?: boolean // where the forge says
  isOutdated?: boolean // attached to a version of the file that has since changed
  oldLine?: number // for a comment on a removed line: its line in the target's version of the file
  // What the forge calls the thread it is in, by which the thread is resolved (and, on GitLab,
  // replied to): GitHub's node id of the review thread, GitLab's discussion id. Absent where the
  // forge did not say, and on general comments.
  thread?: string
}

type Json = Record<string, unknown>

type Place = {
  forge: 'github' | 'gitlab'
  cli: 'gh' | 'glab'
  number: number
  host: string
  repo: string // "owner/repo", or "group/sub/repo"
  label: string // "PR #12" or "MR !34"
  noun: string // "pull request" or "merge request"
}

const COMMENTS_MS = 60_000

const record = (value: unknown): Json => (typeof value === 'object' && value !== null ? (value as Json) : {})

const whole = (value: unknown): number => (typeof value === 'number' && Number.isInteger(value) && value > 0 ? value : 0)

const named = (value: unknown): string => (typeof value === 'string' || typeof value === 'number' ? String(value) : '')

// Every JSON value in a CLI's output, with arrays flattened: a paginated call may print one merged
// array, or one value per page back to back.
const values = (stdout: string): unknown[] => {
  const found: unknown[] = []
  const take = (slice: string) => {
    const parsed: unknown = JSON.parse(slice)

    found.push(...(Array.isArray(parsed) ? (parsed as unknown[]) : [parsed]))
  }

  try {
    take(stdout)

    return found
  } catch {
    found.length = 0
  }

  let depth = 0
  let start = -1
  let isInString = false
  let isEscaped = false

  for (let at = 0; at < stdout.length; at++) {
    const char = stdout[at]

    if (isInString) {
      if (isEscaped) {
        isEscaped = false
      } else if (char === '\\') {
        isEscaped = true
      } else if (char === '"') {
        isInString = false
      }
    } else if (char === '"') {
      isInString = true
    } else if (char === '{' || char === '[') {
      if (depth === 0) {
        start = at
      }

      depth++
    } else if (char === '}' || char === ']') {
      depth--

      if (depth === 0 && start >= 0) {
        take(stdout.slice(start, at + 1))
        start = -1
      }
    }
  }

  if (depth !== 0) {
    throw new Error('cut short')
  }

  return found
}

const call = async (run: Run, argv: string[], timeoutMs = COMMENTS_MS) =>
  run(argv, timeoutMs).catch((error: unknown) => ({ exitCode: -1, stdout: '', stderr: String(error) }))

// What the forge itself said went wrong: the "message" of its JSON answer, else the CLI's last line.
const forgeSaid = (ran: { stdout: string; stderr: string }): string => {
  try {
    const answer = record(JSON.parse(ran.stdout))
    const said = answer.message ?? answer.error

    return [
      typeof said === 'string' ? said : said === undefined ? '' : JSON.stringify(said),
      answer.errors === undefined ? '' : JSON.stringify(answer.errors),
    ].join(' ')
  } catch {
    return lastLine(ran.stderr)
  }
}

// One sentence for a forge call that failed. `doing` is "read" or "comment on".
const whyFailed = (
  place: Place,
  ran: { exitCode: number; stdout: string; stderr: string },
  doing: 'read' | 'comment on',
  at?: { path: string; line: number },
): string => {
  const { cli, label, noun } = place
  const all = `${ran.stderr}\n${ran.stdout}`
  const status = /HTTP (\d{3})/.exec(ran.stderr)?.[1] ?? ''

  if (status === '') {
    if (/timed? ?out/i.test(ran.stderr)) {
      return `${cli} did not answer`
    }

    if (
      ran.exitCode === -1 ||
      ran.exitCode === 127 ||
      /ENOENT|command not found|no such file|not found in \$?PATH/i.test(ran.stderr)
    ) {
      return `${cli} is not installed`
    }
  }

  if (status === '401' || (status === '' && /auth login|not logged in|authenticat|unauthorized|bad credentials/i.test(all))) {
    return `${cli} is not signed in: run ${cli} auth login`
  }

  if (/rate limit/i.test(all) || status === '429') {
    return `${place.forge === 'github' ? 'GitHub' : 'GitLab'} is refusing more calls for now (rate limit): try again in a few minutes`
  }

  if (status === '403') {
    return `You do not have permission to ${doing} this ${noun}`
  }

  if (status === '404' || /could not resolve to a/i.test(all)) {
    return `${label} was not found in ${place.repo}, or you may not see it`
  }

  if (at && (status === '422' || status === '400')) {
    if (/commit_id|head_sha|base_sha|start_sha/i.test(all)) {
      return `This ${noun} has changed since it was opened here: reopen it, then comment again`
    }

    if (/line|diff_hunk|position|path/i.test(all)) {
      return `Line ${at.line} of ${at.path} is not part of this ${noun}'s diff`
    }
  }

  const said = forgeSaid(ran).replace(/\s+/g, ' ').trim().slice(0, 160)

  return doing === 'read'
    ? `The comments of ${label} could not be read: ${said || `${cli} failed`}`
    : `The comment could not be posted on ${label}: ${said || `${cli} failed`}`
}

// Which request `typed` names, on which forge and repo: the same reading of it as resolveRequest.
const locate = async (run: Run, typed: string): Promise<Place | { error: string }> => {
  const request = parseRequest(typed)

  if (!request) {
    return { error: `"${typed.trim()}" is not a PR or MR: type a number like 12, or paste its URL` }
  }

  const remote = await call(run, ['git', 'remote', 'get-url', 'origin'], LOCAL_MS)
  const origin = remote.exitCode === 0 ? remoteParts(remote.stdout) : undefined

  if (!origin || origin.repo === '') {
    return { error: 'This repo has no remote named origin to read a PR or MR from' }
  }

  const known = forgeOf(remote.stdout)
  const forge = known === 'unknown' ? request.host : known

  if (forge === 'unknown') {
    return {
      error: `This repo's origin is not GitHub or GitLab; type "pr ${request.number}" or "mr ${request.number}" to say which it is`,
    }
  }

  if (request.repo !== undefined && request.repo.toLowerCase() !== origin.repo.toLowerCase()) {
    return { error: `That link is for ${request.repo}, but this repo's origin is ${origin.repo}; open that repo instead` }
  }

  return {
    forge,
    cli: forge === 'github' ? 'gh' : 'glab',
    number: request.number,
    host: origin.host,
    repo: origin.repo,
    label: forge === 'github' ? `PR #${request.number}` : `MR !${request.number}`,
    noun: forge === 'github' ? 'pull request' : 'merge request',
  }
}

const byTime = (comments: Comment[]): Comment[] =>
  comments
    .map((comment, index) => ({ comment, index }))
    .sort((one, other) =>
      one.comment.when === other.comment.when
        ? one.index - other.index
        : one.comment.when < other.comment.when
          ? -1
          : 1,
    )
    .map(({ comment }) => comment)

// ---- GitHub ----

type ThreadState = { isResolved: boolean; isOutdated: boolean; id: string }

const THREADS_QUERY =
  'query($owner:String!,$name:String!,$number:Int!,$endCursor:String){repository(owner:$owner,name:$name){' +
  'pullRequest(number:$number){reviewThreads(first:100,after:$endCursor){pageInfo{hasNextPage endCursor}' +
  'nodes{id isResolved isOutdated comments(first:1){nodes{databaseId}}}}}}}'

const gh = (place: Place, ...rest: string[]): string[] => ['gh', 'api', '--hostname', place.host, ...rest]

// One review comment as GitHub's REST API gives it. `threads` is keyed by the id of a thread's first comment.
const fromGithubLine = (raw: unknown, threads: Map<string, ThreadState>): Comment => {
  const one = record(raw)
  const id = named(one.id)
  const replyTo = named(one.in_reply_to_id)
  const thread = threads.get(replyTo || id)
  const isOnFile = one.subject_type === 'file'
  const line = whole(one.line)
  // A comment whose line has since changed keeps only its original_line: `line` comes back null.
  const isOutdated = !isOnFile && line === 0
  const isOnOld = one.side === 'LEFT'

  return {
    id,
    path: text(one.path),
    line: isOnOld ? 0 : line,
    author: text(record(one.user).login) || 'ghost',
    body: typeof one.body === 'string' ? one.body : '',
    when: text(one.created_at),
    ...(replyTo === '' ? {} : { replyTo }),
    ...(thread ? { isResolved: thread.isResolved } : {}),
    ...(thread && thread.id !== '' ? { thread: thread.id } : {}),
    isOutdated,
    ...(isOnOld && line > 0 ? { oldLine: line } : {}),
  }
}

const fromGithubGeneral = (raw: unknown, kind: 'issue' | 'review'): Comment => {
  const one = record(raw)

  return {
    id: `${kind}-${named(one.id)}`,
    path: '',
    line: 0,
    author: text(record(one.user).login) || 'ghost',
    body: typeof one.body === 'string' ? one.body : '',
    when: text(kind === 'issue' ? one.created_at : one.submitted_at),
  }
}

const githubComments = async (run: Run, place: Place): Promise<{ comments: Comment[] } | { error: string }> => {
  const [owner = '', name = ''] = place.repo.split('/')
  const base = `repos/${place.repo}`

  const [lines, talk, reviews, threadPages] = await Promise.all([
    call(run, gh(place, `${base}/pulls/${place.number}/comments?per_page=100`, '--paginate')),
    call(run, gh(place, `${base}/issues/${place.number}/comments?per_page=100`, '--paginate')),
    call(run, gh(place, `${base}/pulls/${place.number}/reviews?per_page=100`, '--paginate')),
    call(
      run,
      gh(
        place,
        'graphql',
        '--paginate',
        '-f',
        `query=${THREADS_QUERY}`,
        '-f',
        `owner=${owner}`,
        '-f',
        `name=${name}`,
        '-F',
        `number=${place.number}`,
      ),
    ),
  ])

  for (const ran of [lines, talk, reviews]) {
    if (ran.exitCode !== 0) {
      return { error: whyFailed(place, ran, 'read') }
    }
  }

  // Resolved state only exists on threads, which only GraphQL lists. Without it the comments
  // are still worth showing, so a failure here is not an error: isResolved is just left out.
  const threads = new Map<string, ThreadState>()

  if (threadPages.exitCode === 0) {
    try {
      for (const page of values(threadPages.stdout)) {
        const listed = record(record(record(record(record(page).data).repository).pullRequest).reviewThreads).nodes

        for (const node of Array.isArray(listed) ? (listed as unknown[]) : []) {
          const thread = record(node)
          const first = (record(thread.comments).nodes as unknown[] | undefined)?.[0]
          const id = named(record(first).databaseId)

          if (id !== '') {
            threads.set(id, {
              isResolved: thread.isResolved === true,
              isOutdated: thread.isOutdated === true,
              id: named(thread.id),
            })
          }
        }
      }
    } catch {
      threads.clear()
    }
  }

  try {
    return {
      comments: byTime([
        ...values(lines.stdout).map(raw => fromGithubLine(raw, threads)),
        ...values(talk.stdout).map(raw => fromGithubGeneral(raw, 'issue')),
        // A review is listed even when it only carried line comments: then its own body is empty.
        ...values(reviews.stdout)
          .map(raw => fromGithubGeneral(raw, 'review'))
          .filter(comment => comment.body.trim() !== '' && comment.when !== ''),
      ]),
    }
  } catch {
    return { error: `The comments of ${place.label} could not be read: gh gave an answer that could not be read` }
  }
}

// ---- GitLab ----

const glab = (place: Place, ...rest: string[]): string[] => ['glab', 'api', '--hostname', place.host, ...rest]

// "group/sub/app" goes in as one encoded path segment, which is how GitLab takes a project by its path.
const gitlabRequest = (place: Place): string =>
  `projects/${encodeURIComponent(place.repo)}/merge_requests/${place.number}`

// One note of a discussion. `headSha` is the request's current head, '' when it is not known.
const fromGitlabNote = (raw: unknown, rootId: string, headSha: string, thread = ''): Comment => {
  const one = record(raw)
  const id = named(one.id)
  const hasPlace = typeof one.position === 'object' && one.position !== null
  const position = record(one.position)
  const madeOn = text(position.head_sha)
  // GitLab moves a note's position along with new commits while its line survives, so a position
  // still naming an older head is one whose line has changed since.
  const isOutdated = hasPlace && headSha !== '' && madeOn !== '' ? madeOn !== headSha : undefined
  const isOnFile = position.position_type !== undefined && position.position_type !== 'text'
  const newLine = whole(position.new_line)
  const oldLine = whole(position.old_line)

  return {
    id,
    path: hasPlace ? text(position.new_path) || text(position.old_path) : '',
    line: isOutdated === true || isOnFile ? 0 : newLine,
    author: text(record(one.author).username) || text(record(one.author).name) || 'ghost',
    body: typeof one.body === 'string' ? one.body : '',
    when: text(one.created_at),
    ...(rootId === id ? {} : { replyTo: rootId }),
    ...(one.resolvable === true ? { isResolved: one.resolved === true } : {}),
    ...(isOutdated === undefined ? {} : { isOutdated }),
    ...(hasPlace && !isOnFile && newLine === 0 && oldLine > 0 ? { oldLine } : {}),
    // Only a thread that can be resolved is kept by its discussion: a general note has none.
    ...(thread === '' || one.resolvable !== true ? {} : { thread }),
  }
}

const fromGitlabDiscussion = (raw: unknown, headSha: string): Comment[] => {
  const listed = record(raw).notes
  const notes = (Array.isArray(listed) ? (listed as unknown[]) : []).filter(note => record(note).system !== true)
  const rootId = named(record(notes[0]).id)

  const thread = named(record(raw).id)

  return notes.map(note => fromGitlabNote(note, rootId, headSha, thread))
}

const gitlabComments = async (run: Run, place: Place): Promise<{ comments: Comment[] } | { error: string }> => {
  const [discussions, request] = await Promise.all([
    call(run, glab(place, `${gitlabRequest(place)}/discussions?per_page=100`, '--paginate')),
    call(run, glab(place, gitlabRequest(place))),
  ])

  if (discussions.exitCode !== 0) {
    return { error: whyFailed(place, discussions, 'read') }
  }

  let headSha = ''

  try {
    headSha = request.exitCode === 0 ? text(record(record(JSON.parse(request.stdout)).diff_refs).head_sha) : ''
  } catch {
    headSha = ''
  }

  try {
    return { comments: byTime(values(discussions.stdout).flatMap(raw => fromGitlabDiscussion(raw, headSha))) }
  } catch {
    return { error: `The comments of ${place.label} could not be read: glab gave an answer that could not be read` }
  }
}

// Where a line of the head version sits in the base version, read from `git diff -U0` output:
// `added` when the line is new, else the line it was. GitLab wants both lines for an unchanged one.
const oldLineOf = (diff: string, line: number): { isAdded: true } | { isAdded: false; oldLine: number } => {
  let shift = 0

  for (const hunk of diff.matchAll(/^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/gm)) {
    const removed = hunk[2] === undefined ? 1 : Number(hunk[2])
    const start = Number(hunk[3])
    const added = hunk[4] === undefined ? 1 : Number(hunk[4])

    if (added > 0 && line >= start && line < start + added) {
      return { isAdded: true }
    }

    // With nothing added, `start` is the line the removal follows.
    if (added > 0 ? start + added - 1 < line : start < line) {
      shift += added - removed
    }
  }

  return { isAdded: false, oldLine: line - shift }
}

const gitlabPost = async (
  run: Run,
  place: Place,
  at: { path: string; line: number; commit: string },
  body: string,
): Promise<{ comment: Comment } | { error: string }> => {
  const request = await call(run, glab(place, gitlabRequest(place)))

  if (request.exitCode !== 0) {
    return { error: whyFailed(place, request, 'comment on') }
  }

  let refs: Json = {}

  try {
    refs = record(record(JSON.parse(request.stdout)).diff_refs)
  } catch {
    refs = {}
  }

  const baseSha = text(refs.base_sha)
  const startSha = text(refs.start_sha)
  const headSha = text(refs.head_sha)

  if (baseSha === '' || startSha === '' || headSha === '') {
    return { error: `The comment could not be posted on ${place.label}: glab did not say which commits it compares` }
  }

  if (headSha !== at.commit) {
    return { error: 'This merge request has changed since it was opened here: reopen it, then comment again' }
  }

  // GitLab places a note by old and new line together. Git knows both when the commits are here;
  // when they are not, the new line alone is sent, which GitLab accepts for added lines.
  const outside = { error: `Line ${at.line} of ${at.path} is not part of this merge request's diff` }
  let oldPath = at.path
  let oldLine = 0

  const changed = await call(run, ['git', 'diff', '--name-status', '-M', '-z', baseSha, headSha, '--'], LOCAL_MS)

  if (changed.exitCode === 0) {
    const fields = changed.stdout.split('\0')
    let status = ''

    for (let index = 0; index < fields.length - 1; ) {
      const kind = fields[index] ?? ''
      const isMoved = /^[RC]/.test(kind)
      const from = fields[index + 1] ?? ''
      const to = isMoved ? (fields[index + 2] ?? '') : from

      if (to === at.path) {
        status = kind
        oldPath = from
      }

      index += isMoved ? 3 : 2
    }

    if (status === '' || status.startsWith('D')) {
      return outside
    }

    if (!status.startsWith('A')) {
      const diff = await call(
        run,
        ['git', 'diff', '--no-color', '--no-ext-diff', '-U0', '-M', baseSha, headSha, '--', ...new Set([oldPath, at.path])],
        LOCAL_MS,
      )
      const where = diff.exitCode === 0 ? oldLineOf(diff.stdout, at.line) : { isAdded: true as const }

      oldLine = where.isAdded ? 0 : where.oldLine
    }
  }

  // glab sends fields as a JSON body, where a name like position[new_line] would be one literal key
  // that GitLab ignores; -F parses a JSON object, so the position travels as one.
  const position = {
    position_type: 'text',
    base_sha: baseSha,
    start_sha: startSha,
    head_sha: headSha,
    old_path: oldPath,
    new_path: at.path,
    new_line: at.line,
    ...(oldLine > 0 ? { old_line: oldLine } : {}),
  }

  const posted = await call(
    run,
    glab(
      place,
      '-X',
      'POST',
      `${gitlabRequest(place)}/discussions`,
      '-f',
      `body=${body}`,
      '-F',
      `position=${JSON.stringify(position)}`,
    ),
  )

  if (posted.exitCode !== 0) {
    return { error: whyFailed(place, posted, 'comment on', at) }
  }

  try {
    const comment = fromGitlabDiscussion(JSON.parse(posted.stdout), headSha)[0]

    if (!comment) {
      throw new Error('no note')
    }

    // An older glab that does not send the position would post a general comment instead.
    return comment.path === ''
      ? { error: `The comment was posted on ${place.label}, but not on the line: update glab, and move it on GitLab` }
      : { comment }
  } catch {
    return { error: `The comment may have been posted on ${place.label}, but glab's answer could not be read: reload to check` }
  }
}

// ---- The three entry points ----

// Every comment on the request, oldest first: review comments on lines, and the general conversation.
// `typed` is what the person typed to open the request ("#12", a URL, ...), as resolveRequest takes.
// The open pull or merge request whose head is a branch of this repo, by
// what a person would type to open it ("#12") and how it is spoken of
// ("PR #12"); undefined when there is none, or no forge to ask.
export const requestOfBranch = async (
  run: Run,
  branch: string,
): Promise<
  { typed: string; label: string; title: string; baseRef: string; url: string } | undefined
> => {
  if (branch === '' || branch === 'HEAD') {
    return undefined
  }

  const place = await locate(run, '1')

  if ('error' in place) {
    return undefined
  }

  const isGitlab = place.forge === 'gitlab'
  const asked = await call(
    run,
    isGitlab
      ? glab(
          place,
          `projects/${encodeURIComponent(place.repo)}/merge_requests?state=opened&source_branch=${encodeURIComponent(branch)}`,
        )
      : gh(
          place,
          `repos/${place.repo}/pulls?state=open&head=${encodeURIComponent(`${place.repo.split('/')[0] ?? ''}:${branch}`)}`,
        ),
    20_000,
  )

  if (asked.exitCode !== 0) {
    return undefined
  }

  try {
    const first = record(values(asked.stdout)[0])
    const number = whole(isGitlab ? first.iid : first.number)

    // What it is called, and the branch it asks to be merged into.
    const title = text(first.title)
    const baseRef = isGitlab ? text(first.target_branch) : text(record(first.base).ref)
    // Its page on the forge.
    const url = isGitlab ? text(first.web_url) : text(first.html_url)

    return number === 0
      ? undefined
      : isGitlab
        ? { typed: `!${number}`, label: `MR !${number}`, title, baseRef, url }
        : { typed: `#${number}`, label: `PR #${number}`, title, baseRef, url }
  } catch {
    return undefined
  }
}

// The repo's open pull or merge requests, newest first, each by what a person
// would type to open it ("#12", "!34") and its title. None where there is no
// forge to ask, or it does not answer: a list to offer, never an error.
export const listRequests = async (run: Run): Promise<{ typed: string; title: string }[]> => {
  const place = await locate(run, '1')

  if ('error' in place) {
    return []
  }

  const listed = await call(
    run,
    place.forge === 'gitlab'
      ? glab(place, `projects/${encodeURIComponent(place.repo)}/merge_requests?state=opened&per_page=30`)
      : gh(place, `repos/${place.repo}/pulls?state=open&per_page=30`),
    20_000,
  )

  if (listed.exitCode !== 0) {
    return []
  }

  try {
    return values(listed.stdout).flatMap(raw => {
      const one = record(raw)
      const number = whole(place.forge === 'gitlab' ? one.iid : one.number)

      return number === 0
        ? []
        : [{ typed: `${place.forge === 'gitlab' ? '!' : '#'}${number}`, title: text(one.title) }]
    })
  } catch {
    return []
  }
}

export const fetchComments = async (run: Run, typed: string): Promise<{ comments: Comment[] } | { error: string }> => {
  const place = await locate(run, typed)

  if ('error' in place) {
    return place
  }

  return place.forge === 'github' ? githubComments(run, place) : gitlabComments(run, place)
}

// Posts one review comment on a line of the request's head version of a file. `at.commit` is the
// full hash of the head commit the comment is anchored to; `at.path` is relative to the repo root.
export const postComment = async (
  run: Run,
  typed: string,
  at: { path: string; line: number; commit: string },
  body: string,
): Promise<{ comment: Comment } | { error: string }> => {
  if (body.trim() === '') {
    return { error: 'Write something before posting the comment' }
  }

  if (at.path === '' || !Number.isInteger(at.line) || at.line < 1 || at.commit === '') {
    return { error: 'Pick a line of a file in the request to comment on' }
  }

  const place = await locate(run, typed)

  if ('error' in place) {
    return place
  }

  if (place.forge === 'gitlab') {
    return gitlabPost(run, place, at, body)
  }

  // -f keeps the body as typed (-F would read "@file" and turn "true" into a boolean); the line must be a number.
  const posted = await call(
    run,
    gh(
      place,
      '-X',
      'POST',
      `repos/${place.repo}/pulls/${place.number}/comments`,
      '-f',
      `body=${body}`,
      '-f',
      `commit_id=${at.commit}`,
      '-f',
      `path=${at.path}`,
      '-F',
      `line=${at.line}`,
      '-f',
      'side=RIGHT',
    ),
  )

  if (posted.exitCode !== 0) {
    return { error: whyFailed(place, posted, 'comment on', at) }
  }

  try {
    return { comment: fromGithubLine(JSON.parse(posted.stdout), new Map()) }
  } catch {
    return { error: `The comment may have been posted on ${place.label}, but gh's answer could not be read: reload to check` }
  }
}

// Answers a review thread. `root` is the thread's first comment: GitHub replies to that comment
// by its id, GitLab adds a note to the discussion (`root.thread`).
export const replyComment = async (
  run: Run,
  typed: string,
  root: Pick<Comment, 'id' | 'thread'>,
  body: string,
): Promise<{ comment: Comment } | { error: string }> => {
  if (body.trim() === '') {
    return { error: 'Write something before posting the reply' }
  }

  const place = await locate(run, typed)

  if ('error' in place) {
    return place
  }

  if (place.forge === 'gitlab' && (root.thread ?? '') === '') {
    return { error: 'GitLab did not say which discussion that comment is in: refresh (r) and try again' }
  }

  const posted = await call(
    run,
    place.forge === 'gitlab'
      ? glab(
          place,
          '-X',
          'POST',
          `${gitlabRequest(place)}/discussions/${root.thread ?? ''}/notes`,
          '-f',
          `body=${body}`,
        )
      : gh(
          place,
          '-X',
          'POST',
          `repos/${place.repo}/pulls/${place.number}/comments/${root.id}/replies`,
          '-f',
          `body=${body}`,
        ),
  )

  if (posted.exitCode !== 0) {
    return { error: whyFailed(place, posted, 'comment on') }
  }

  try {
    const made =
      place.forge === 'gitlab'
        ? fromGitlabNote(JSON.parse(posted.stdout), root.id, '', root.thread ?? '')
        : fromGithubLine(JSON.parse(posted.stdout), new Map())

    return { comment: { ...made, replyTo: root.id } }
  } catch {
    return { error: `The reply may have been posted on ${place.label}, but the answer could not be read: refresh to check` }
  }
}

// Marks a review thread resolved, or open again. Answers '' when the forge took it, else why not.
export const resolveThread = async (
  run: Run,
  typed: string,
  thread: string,
  isResolved: boolean,
): Promise<string> => {
  const place = await locate(run, typed)

  if ('error' in place) {
    return place.error
  }

  if (thread === '') {
    return `${place.label} did not say which thread that comment is in: refresh (r) and try again`
  }

  const verb = isResolved ? 'resolveReviewThread' : 'unresolveReviewThread'
  const ran = await call(
    run,
    place.forge === 'gitlab'
      ? glab(
          place,
          '-X',
          'PUT',
          `${gitlabRequest(place)}/discussions/${thread}?resolved=${isResolved ? 'true' : 'false'}`,
        )
      : gh(
          place,
          'graphql',
          '-f',
          `query=mutation($id:ID!){${verb}(input:{threadId:$id}){thread{isResolved}}}`,
          '-f',
          `id=${thread}`,
        ),
  )

  return ran.exitCode === 0 ? '' : whyFailed(place, ran, 'comment on')
}

// Submits a review of the request: an approval, a request for changes, or a
// comment, with a summary. Answers '' when the forge took it, else why not.
export const submitReview = async (
  run: Run,
  typed: string,
  verdict: 'approve' | 'request-changes' | 'comment',
  summary: string,
): Promise<string> => {
  const body = summary.trim()

  if (verdict !== 'approve' && body === '') {
    return 'Write a summary first: it is what the review says'
  }

  const place = await locate(run, typed)

  if ('error' in place) {
    return place.error
  }

  if (place.forge === 'gitlab') {
    if (verdict === 'request-changes') {
      return 'GitLab has no call for requesting changes here: submit a comment saying what to change'
    }

    if (verdict === 'approve') {
      const approved = await call(run, glab(place, '-X', 'POST', `${gitlabRequest(place)}/approve`))

      if (approved.exitCode !== 0) {
        return whyFailed(place, approved, 'comment on')
      }
    }

    if (body === '') {
      return ''
    }

    const noted = await call(
      run,
      glab(place, '-X', 'POST', `${gitlabRequest(place)}/notes`, '-f', `body=${body}`),
    )

    return noted.exitCode === 0 ? '' : whyFailed(place, noted, 'comment on')
  }

  const event = verdict === 'approve' ? 'APPROVE' : verdict === 'comment' ? 'COMMENT' : 'REQUEST_CHANGES'
  const sent = await call(
    run,
    gh(
      place,
      '-X',
      'POST',
      `repos/${place.repo}/pulls/${place.number}/reviews`,
      '-f',
      `event=${event}`,
      ...(body === '' ? [] : ['-f', `body=${body}`]),
    ),
  )

  return sent.exitCode === 0 ? '' : whyFailed(place, sent, 'comment on')
}

// The sub-folder of the repo that `run` executes in, as a prefix ('' at the root, 'frontend/' in a
// sub-folder): the pane may be reviewing a sub-folder, and forge paths are relative to the root.
export const repoPrefix = async (run: Run): Promise<string> => {
  const ran = await call(run, ['git', 'rev-parse', '--show-prefix'], LOCAL_MS)

  return ran.exitCode === 0 ? ran.stdout.trim() : ''
}

files.hooks/run.ts:
// How a module that holds no engine handle runs a command. The hooks module,
// which holds the handle, passes each such module a `Run`; everything below
// it knows processes only through this.

export type Ran = { exitCode: number; stdout: string; stderr: string }

// Runs a command and never rejects: one that could not be started answers
// exit code -1 with the reason as its stderr, so a caller has one thing to
// check and nothing to catch.
export type Run = (
  argv: string[],
  init?: { cwd?: string; stdin?: string; timeoutMs?: number },
) => Promise<Ran>

// More files than this are not handed to one command.
export const FILE_LIMIT = 300

// The last words of what a command printed, short enough for a note or a toast.
export const tail = (text: string): string => text.trim().split('\n').slice(-2).join(' ').slice(0, 200)

files.hooks/scan.ts:
// The scan: one pass over the comparison under review. It asks git what
// differs, shows that at once, has the files checked, and publishes what is
// found as it comes in. It holds no engine handle: the hooks module passes
// it the ports it works through.

import type { Diag, GraphRow, Scan } from '../types'
import type { Progress } from './check'
import { checkChange, isCheckable, refreshServed, toolsAwaited, uncheckedNotes } from './check'
import { isFadeOnly } from './diags'
import * as git from './git'
import type { Run as ServerRun } from './lsp'
import { issueList } from './prompt'
import type { Run } from './run'
import type { Checkers } from './settings'

// How many files are checked at a time. A batch is one run of each checker
// and cannot be added to once started, so the file a person opens waits for
// the batch under way: a smaller batch is a shorter wait, at the price of
// starting the checkers more often.
export const BATCH = 100

// How many issues an automatic note tells Claude.
const ISSUES_TOLD = 15

// What a scan is asked to do beyond the changed files: `isProject` checks
// every file of every project with the command-line checkers.
export type Job = { isProject: boolean }

// What is under review, as the pane's state has it when the scan starts.
export type Subject = {
  repo: string
  base: string
  // The commit compared against the base in place of the working tree, or ''.
  target: string
  // Unchanged files to check along with the changed.
  extra: readonly string[]
  // Whether the list of every tracked file is wanted too.
  isBrowsing: boolean
  // Whether Claude is told what its own edits broke.
  isTelling: boolean
  // What was typed to open the request under review, or ''.
  requestTyped: string
  // The checkers left switched on, and whether new is told from pre-existing.
  use: Checkers
  marksNew: boolean
}

export type Ports = {
  run: Run
  servers: ServerRun
  // A file's text by its absolute path; '' for one that cannot be read.
  readFile: (path: string) => Promise<string>
  // The scan's own state: as it stands, and a change to it.
  readScan: () => Promise<Scan>
  writeScan: (change: (last: Scan) => Scan) => Promise<unknown>
  // Called once git has answered and the changed files are published, before
  // the checkers start: the moment to read an open file again.
  onListed: () => Promise<void>
  // Reads the request's comments again; answers '' or why it could not.
  readComments: (typed: string) => Promise<string>
  // The one-line summary for the status line; '' clears it.
  showStatus: (text: string) => void
  // A note to Claude, in the conversation.
  tellClaude: (text: string) => Promise<unknown>
  // The file the person has open as the scan's side has it, or '': asked
  // before each batch, since that file is checked next.
  openFile: () => Promise<string>
  // Whether another scan has been asked for since this one started: a long
  // scan then stops between batches and leaves the rest to that one.
  isOvertaken: () => boolean
}

// The whole history as the graph lays it out. Thousands of rows are too much
// to keep as state, so a reload drops them and the scan it starts reads them
// again. Written by `scanRepo` alone; read through `historyOf`.
let history: { repo: string; rows: GraphRow[] } | undefined

// Every file git tracks in the folder under review, read while the tree of
// all files is showing; too many paths to keep as state. Written by
// `scanRepo` alone; read through `allFilesOf`.
let allFiles: { repo: string; paths: string[] } | undefined

// The files Claude has edited since it was last told about its new problems,
// relative to the folder under review (added through `noteTouched`), and the
// problems it has been told.
// The files of the scan under way that no batch has reached yet. Written by
// `scanRepo` alone; read through `isQueued`. The scan's `checked` count
// changing is what redraws the readers.
let queued: { repo: string; paths: Set<string> } | undefined

const touched = new Set<string>()
const told = new Set<string>()

// The history of the repo last scanned, when that is `repo`; else none yet.
export const historyOf = (repo: string): GraphRow[] =>
  history !== undefined && history.repo === repo ? history.rows : []

// Every tracked file of the repo last scanned with `isBrowsing`, when that
// is `repo`; else none yet.
export const allFilesOf = (repo: string): string[] =>
  allFiles !== undefined && allFiles.repo === repo ? allFiles.paths : []

// Whether a file of the scan under way is still waiting for its batch.
export const isQueued = (repo: string, path: string): boolean =>
  queued !== undefined && queued.repo === repo && queued.paths.has(path)

// Why git could not compare with the base, with what to do about it.
const explainDiff = (base: string, refusal: string): string =>
  /unknown revision|bad revision|ambiguous argument|not a valid object/i.test(refusal)
    ? `"${base}" is not a branch or commit in this repo, so nothing is compared. Pick one from the graph, or run /lens again with another`
    : `git could not compare with ${base}: ${refusal}`

// Notes a file Claude edited, for the next scan to tell it what that broke.
export const noteTouched = (path: string): void => {
  touched.add(path)
}

export const scanRepo = async (
  ports: Ports,
  { repo, base, target, extra, isBrowsing, isTelling, requestTyped, use, marksNew }: Subject,
  { isProject }: Job,
): Promise<void> => {
  if (repo === '') {
    return
  }

  await ports.writeScan((last): Scan => ({ ...last, status: 'running' }))

  const notes: string[] = []
  // Which languages have a server is asked while git answers: a server
  // installed, or added to the person's config file, since the last scan
  // counts from this one on.
  const [changes, misconfigured] = await Promise.all([
    git.readChanges(ports.run, repo, base, target),
    refreshServed(ports.servers, use.servers),
  ])

  if (changes.refusal !== undefined) {
    notes.push(explainDiff(base, changes.refusal))
  }

  notes.push(...misconfigured)

  const live = changes.files.filter(one => one.status !== 'D').map(one => one.path)
  // The files to check: what differs, and the unchanged files the person
  // opened from the tree of every file.
  const wanted = [...live, ...(target === '' ? extra : []).filter(path => !live.includes(path))]

  notes.push(...uncheckedNotes(wanted))

  if (isBrowsing) {
    allFiles = { repo, paths: await git.trackedFiles(ports.run, repo) }
  }

  // The files are checked a batch at a time, so the first results show
  // while the rest wait their turn.
  let left = wanted.filter(isCheckable)
  const toCheck = left.length
  const finished = new Set<string>()
  const waiting = new Set(left)

  queued = { repo, paths: waiting }

  history = { repo, rows: changes.history }

  // What git alone answers (the files that differ, their line counts, the
  // history) is shown at once; the checkers, which take the time, fill the
  // diagnostics in when they are done.
  const listed = {
    files: changes.files,
    changed: changes.changed,
    stats: changes.stats,
    // The rows themselves are the module's (`history`); the count changing
    // is what redraws the graph.
    graph: [] as GraphRow[],
    graphCount: changes.history.length,
    branches: changes.branches,
    head: changes.head,
    headHash: changes.headHash,
    dirty: changes.dirty,
    stashes: changes.stashes,
    worktrees: changes.worktrees,
  }

  await ports.writeScan(
    (last): Scan => ({
      ...last,
      ...listed,
      pending: [],
      status: 'running',
      notes: [...notes],
      checked: 0,
      toCheck,
    }),
  )
  await ports.onListed()

  const targetHash = target === '' ? '' : await git.shortHash(ports.run, repo, target)
  const baseShort = await git.shortHash(ports.run, repo, base)

  // The scan as it goes: which tools are still running, and what they have
  // found so far. A tool that has not reported yet keeps what it found last
  // time, so a count does not drop to nothing and climb back. The writes are
  // chained, so they land in order and none is left to land after the last.
  const previous = (await ports.readScan()).diags
  const running: string[] = []
  let written: Promise<unknown> = Promise.resolve()
  const publish = (found?: Diag[]): Promise<unknown> => {
    const awaited = toolsAwaited(running)

    written = written.then(() =>
      ports.writeScan(
        (last): Scan => ({
          ...last,
          pending: [...running],
          checked: finished.size,
          diags:
            found === undefined
              ? last.diags
              : [
                  ...found,
                  ...previous.filter(
                    old =>
                      // What was known of a file no batch has reached yet
                      // stands until its turn; of the others, what a tool
                      // still out said last time.
                      (waiting.has(old.path) ||
                        (awaited.has(old.tool) && !finished.has(old.path))) &&
                      !found.some(
                        one =>
                          one.path === old.path &&
                          one.line === old.line &&
                          one.tool === old.tool &&
                          one.message === old.message,
                      ),
                  ),
                ]
                  .filter(diag => !isFadeOnly(diag))
                  .slice(0, 5000),
        }),
      ),
    )

    return written
  }
  // What the batches before the one under way found.
  const diags: Diag[] = []
  const progress: Progress = {
    start: tool => {
      running.push(tool)
      void publish()
    },
    done: (tool, found) => {
      const at = running.indexOf(tool)

      if (at !== -1) {
        running.splice(at, 1)
      }

      void publish([...diags, ...found])
    },
  }

  for (let round = 0; round === 0 || left.length > 0; round += 1) {
    // The file the person is reading is checked next, whatever its place.
    const open = await ports.openFile()

    if (left.includes(open)) {
      left = [open, ...left.filter(path => path !== open)]
    }

    const batch = left.slice(0, BATCH)

    left = left.slice(BATCH)

    for (const path of batch) {
      waiting.delete(path)
    }

    const answer = await checkChange(
      {
        run: ports.run,
        servers: ports.servers,
        readFile: ports.readFile,
      },
      {
        repo,
        base: { ref: base, short: baseShort },
        target: { ref: target, short: targetHash },
        files: changes.files,
        // What no checker reads rides with the first batch: a whole-project
        // check is asked once, and finds what it finds wherever it is.
        wanted: round === 0 ? [...batch, ...wanted.filter(path => !isCheckable(path))] : batch,
        isProject: isProject && round === 0,
        use,
        marksNew,
      },
      progress,
    )

    diags.push(...answer.diags)
    notes.push(...answer.notes.filter(note => !notes.includes(note)))

    for (const path of batch) {
      finished.add(path)
    }

    await publish([...diags])

    // A scan asked for meanwhile takes over from here: it starts with what
    // this one found, and the open file first.
    if (left.length > 0 && ports.isOvertaken()) {
      return
    }
  }

  // Every write the scan made along the way has landed before its last one.
  await written
  queued = undefined

  // A request under review has its comments read with every scan, so a
  // refresh picks up what was said since.
  if (requestTyped !== '') {
    const refusal = await ports.readComments(requestTyped)

    if (refusal !== '') {
      notes.push(`comments were not read: ${refusal}`)
    }
  }

  await ports.writeScan(
    (): Scan => ({
      ...listed,
      pending: [],
      status: 'done',
      // A hint that code is never used fades that code and is no problem to
      // count or list, as in an editor.
      diags: diags.filter(diag => !isFadeOnly(diag)).slice(0, 5000),
      faded: diags.filter(isFadeOnly).slice(0, 2000),
      notes,
      isProjectChecked: isProject,
      checked: toCheck,
      toCheck,
    }),
  )

  // The count rides in the status line too, so a glance tells whether the
  // working tree is clean without the pane open. Each mod has its own entry
  // there, so this sits beside any other mod's.
  const changedPaths = new Set(changes.files.map(one => one.path))
  const mine = diags.filter(diag => changedPaths.has(diag.path))
  const errorCount = mine.filter(diag => diag.severity === 'error').length

  ports.showStatus(
    // The engine writes the mod's name before its entry, so the entry is the count alone.
    // A clean change has nothing to say: '' takes the entry off the status line.
    mine.length === 0 ? '' : `✖ ${errorCount} ⚠ ${mine.length - errorCount}`,
  )

  // Where the person asked for it, Claude is told what its own edits broke:
  // the problems this scan found in the files it changed that the base did
  // not have, each of them once.
  if (isTelling && target === '' && touched.size > 0) {
    const fresh = diags.filter(
      diag =>
        touched.has(diag.path) &&
        diag.isNew !== false &&
        diag.severity !== 'info' &&
        !told.has(`${diag.path}\n${diag.tool}\n${diag.rule}\n${diag.message}`),
    )

    touched.clear()

    if (fresh.length > 0) {
      for (const diag of fresh) {
        told.add(`${diag.path}\n${diag.tool}\n${diag.rule}\n${diag.message}`)
      }

      await ports.tellClaude(
        `lens (automatic note, switched on by the user): after your edits, the checkers report ${fresh.length} new ${fresh.length === 1 ? 'problem' : 'problems'} in files you changed.\n${issueList(fresh, ISSUES_TOLD)}`,
      )
    }
  }
}

files.hooks/screens/file.tsx:
// The file screen: a whole file in a window of the screen's own, with each
// line's diagnostics and review comments beside it, the lines the other side
// had (the diff view), who last changed each line (blame), a breadcrumb that
// opens lists to jump from, a search, and the card of a looked-up name.
//
// Only the lines the window has rows for are drawn, so the tree stays small
// however long the file is; what the scroll hook needs to move the window is
// returned with it.

import type { RenderChildren } from 'claude-code'

import type { Crumb, Diag, LineRange, Lookup, Span } from '../../types'
import { countLabel, diagsByLine } from '../diags'
import type { Blamed } from '../git'
import { kindColor } from '../lists'
import type { InlayHint, OutlineItem, SemanticToken } from '../lsp-types'
import type { MiniLine } from '../minimap'
import { minimapCells } from '../minimap'
import { markSpans, withInlays } from '../parts'
import type { Comment } from '../review'
import { applySemantic, enclosing, outlineRows } from '../semantic'
import { clamp, findMatches, shortRef, wrapText } from '../text'
import { iconOf } from '../tree'
import type { Kit, Shell } from './frame'
import {
  CARD_BACKGROUND,
  COLOR,
  COMMENT_COLOR,
  COMMENT_ICON,
  RESOLVED_COLOR,
  COMMIT_BOX,
  MARK,
  helpButton,
  notesOf,
  said,
  statusLine,
} from './frame'
import { isMarkdownFile } from './markdown'

// The blame column: a short hash, eight letters of the author, how long ago.
const BLAME_WIDTH = 21
// How many lines of a looked-up name's type and docs the file screen shows.
const SYMBOL_LINES = 8
// The narrowest the breadcrumb's popover is; it widens to its longest entry.
const CRUMB_WIDTH = 46
const ADDED_BACKGROUND = '#1f3a24'
const FOUND_BACKGROUND = '#7a4a00'
const REMOVED_BACKGROUND = '#4b1d1d'
// The most removed lines drawn above one line; the window cannot scroll
// inside a run of them, so a longer run is cut with a count.
const REMOVED_LINES = 20
const MINIMAP_COLUMNS = 6
// The minimap is a small corner block, not a full-height column.
const MINIMAP_ROWS = 12
// A pane narrower than this has no room to spare for the minimap.
const MINIMAP_FROM_COLUMNS = 60

// What the language server knows of the file: the file's own lines (a server
// counts a tab as one column, the screen draws four), its outline, what each
// name is, and its inlay hints, by line.
export type Insight = {
  raw: string[]
  items: OutlineItem[]
  tokens: Map<number, SemanticToken[]>
  hints: Map<number, InlayHint[]>
}

// How many lines of a comment show while the file is not expanded.
const TALK_FOLDED = 3

export type FileModel = {
  shell: Shell
  file: string
  // The commit the file is shown at; '' for the working tree's.
  commit: string
  // Whether the file as shown is what the checkers ran on: the working
  // tree's, or the comparison's own target. Only then has it diagnostics.
  isChecked: boolean
  // The file's coloured lines, and the same as plain text; undefined while
  // they are being read. `note` says why highlighting did not run, if so.
  lines: readonly Span[][] | undefined
  texts: readonly string[]
  note: string
  // The lines the other side had, by the line they came before; the lines
  // this side changed; and whether the other side has no such file at all.
  removed: Readonly<Record<number, string[]>>
  changed: readonly LineRange[]
  isNewFile: boolean
  // The file's diagnostics, sorted, and the code said to be never used.
  diags: readonly Diag[]
  faded: readonly Diag[]
  // Who last changed each line, while the blame column shows.
  blame: readonly Blamed[] | undefined
  insight: Insight | undefined
  // The first line of the window (1-based), the diagnostic stepped to (its
  // place among `diags`, -1 for none), and the switches of the view.
  top: number
  cursor: number
  isExpanded: boolean
  isDiff: boolean
  isMore: boolean
  isHinting: boolean
  // The search: whether its field shows, what is typed, the match the
  // person is on.
  isFinding: boolean
  find: string
  findAt: number
  // A request's review: whether this file can be commented on, whether a
  // line number now picks the line to comment on, the line picked (0 for
  // none yet), and what was said on this file's lines.
  canComment: boolean
  isCommenting: boolean
  commentLine: number
  // The thread being answered, by its first comment's id; '' for none.
  replyTo: string
  // What the diff is against, by name, when that is not the comparison's
  // base: the branch a request targets. '' otherwise.
  diffAgainst: string
  // Whether resolved threads are being left out (they are then not in `talk`).
  hidesResolved: boolean
  // Counts the comments sent or dropped: the field keeps its own text under
  // its key, so each new comment gets a field of its own, empty.
  commentRound: number
  talk: readonly Comment[]
  // The breadcrumb's open list, and what the folder it last opened holds.
  crumb: Crumb
  folder: { dir: string; entries: readonly string[] } | undefined
  // The name last looked up in this file.
  symbol: Lookup | undefined
}

export type FileActions = {
  // Returns to where the file was opened from.
  back: () => void
  help: () => void
  refresh: () => void
  toggleMore: () => void
  // Moves the window so `line` is its first.
  scrollTo: (line: number) => void
  // Steps to a diagnostic (its place among the file's), opening its card.
  showIssue: (index: number, top: number) => void
  // Goes to the next place the file differs; `top` is undefined when there
  // is none below.
  nextChange: (top: number | undefined) => void
  toggleDiff: () => void
  toggleExpanded: () => void
  toggleBlame: () => void
  toggleHints: () => void
  // Shows a markdown file rendered again.
  showRendered: () => void
  // The search: its field opened (or given the keyboard back), typed in,
  // a match gone to, the keyboard handed back to the pane's keys, closed.
  find: () => void
  typeFind: (text: string) => void
  showMatch: (index: number, top: number) => void
  leaveFindField: () => void
  closeFind: () => void
  // Pressing a line's number: its block goes to the prompt, or, while
  // commenting, the line is picked to comment on.
  pressLine: (line: number) => void
  // Puts a line's diagnostics, with its code, into the prompt.
  sendIssues: (line: number) => void
  // Puts the review thread on a line, with the code it is about, into the prompt.
  sendTalk: (line: number) => void
  // Opens the comment box under a line as an answer to the thread there, and
  // marks that thread resolved or open again. Both write to the forge only
  // once the person posts or presses.
  replyOn: (line: number) => void
  resolveOn: (line: number, isResolved: boolean) => void
  cancelComment: () => void
  // Leaves resolved threads out, or shows them again; lists every thread.
  toggleResolved: () => void
  listThreads: () => void
  // Puts what was dragged over into the prompt.
  sendSelection: () => void
  // Looks up the name dragged over, among the lines `from`..`to` on screen.
  lookUpSelection: (from: number, to: number) => void
  closeLookup: () => void
  listUses: () => void
  listCallers: () => void
  listCallees: () => void
  listImplementations: () => void
  // Opens a file of the working tree at a line.
  openFile: (path: string, line: number) => void
  // Opens the commit that last changed a line, in the graph.
  openCommit: (hash: string) => void
  // The breadcrumb: a folder's list opened under column `left` (or closed
  // if it is the one open), the same for the names at a level of the
  // outline, a folder listed in the list already open, and the list closed.
  toggleFolder: (dir: string, left: number) => void
  toggleNames: (level: number, left: number) => void
  listFolder: (dir: string, left: number) => void
  closeCrumb: () => void
  // Scrolls to a name picked from the breadcrumb's list, and closes it.
  jumpTo: (line: number) => void
  // Commenting on a request: switched on or off, typed, and posted (Enter
  // passes the field's text; the button posts what was typed so far).
  toggleCommenting: () => void
  typeComment: (text: string) => void
  postComment: (entered?: string) => void
}

// The window as drawn, for the scroll hook: the furthest its first line may
// go (where the file's last line sits on the bottom row), and where the
// breadcrumb's open list sits among the pane's rows (which rows are over it,
// where it is scrolled to, and how far it can go), if one is open.
export type FileWindow = {
  maxTop: number
  crumbBox: { from: number; to: number; top: number; max: number } | undefined
}

export const fileScreen = (
  kit: Kit,
  model: FileModel,
  actions: FileActions,
): { tree: RenderChildren; window: FileWindow } => {
  const { Box, Button, Text, Input, Raster } = kit
  const { shell, file, commit, lines, texts, removed, changed, isNewFile, diags, blame } = model
  const { isDiff, isMore, isFinding, isCommenting, commentLine, crumb, symbol } = model
  const info = model.insight
  const lineCount = lines?.length ?? 0
  const byLine = diagsByLine(diags, lineCount)
  const columns = shell.columns
  const hasMinimap = Raster !== undefined && columns >= MINIMAP_FROM_COLUMNS
  const blameWidth = blame === undefined ? 0 : BLAME_WIDTH + 1
  const codeColumns = columns - (hasMinimap ? MINIMAP_COLUMNS + 1 : 0) - blameWidth
  const gutter = String(Math.max(1, lineCount)).length
  const cardWidth = Math.max(24, Math.min(90, codeColumns - gutter - 4))
  // The code the checkers say is never used, by line.
  const fadedByLine = new Map<number, Diag[]>()

  for (const diag of model.faded) {
    fadedByLine.set(diag.line, [...(fadedByLine.get(diag.line) ?? []), diag])
  }

  // Where the outline's functions and classes start, for the minimap: only
  // the top two levels, or a long file's map is all outline.
  const heads = new Map<number, 1 | 2>()

  for (const item of info?.items ?? []) {
    if (item.depth <= 1 && ['function', 'method', 'constructor'].includes(item.kind)) {
      heads.set(item.line, 1)
    } else if (item.depth <= 1 && ['class', 'interface', 'type', 'enum'].includes(item.kind)) {
      heads.set(item.line, 2)
    }
  }

  // What the language server said of the name last looked up, wrapped to
  // the pane and cut to a few lines: its type or signature, then its docs.
  const symbolLines =
    symbol === undefined
      ? []
      : wrapText(symbol.text === '' ? 'The language server has nothing on that name.' : symbol.text, columns - 6).slice(
          0,
          SYMBOL_LINES,
        )
  // How many lines the breadcrumb needs: each part is its icon, its name
  // and a separator, and a part that does not fit goes to the next line.
  const crumbLength =
    (file.startsWith('/') ? [file] : file.split('/')).reduce(
      (sum, part) => sum + part.length + 5,
      0,
    ) +
    (info === undefined ? [] : enclosing(info.items, model.top)).reduce(
      (sum, item) => sum + item.name.length + 5,
      2,
    )
  const crumbLines = clamp(Math.ceil(crumbLength / columns), 1, 3)
  // The rows the header takes: status, the buttons (which wrap in a narrow
  // pane), each note, and the title. The window gets what is left.
  const headerRows =
    // The status, the breadcrumb and the title.
    2 +
    crumbLines +
    // Its box: a border above and below, the name, the lines, the call it
    // sits in when there is one, and two rows of buttons.
    (symbol === undefined ? 0 : symbolLines.length + 5 + (symbol.signature === '' ? 0 : 1)) +
    (isDiff ? 1 : 0) +
    (isFinding ? 3 : 0) +
    (isCommenting ? 1 : 0) +
    // The main row of buttons, and the box of the rest when it is open.
    Math.ceil(100 / columns) +
    (isMore ? 2 + Math.ceil(170 / Math.max(20, columns - 4)) : 0) +
    shell.notes.length + (model.note === '' ? 0 : 1)
  const room = clamp(shell.rows - headerRows, 5, 256)
  // Both are settled further down, once each line's height is known.
  let top = clamp(model.top, 1, lineCount)
  let maxTop = Math.max(1, lineCount)

  const moveTo = (line: number) => actions.scrollTo(clamp(line, 1, maxTop))
  // The next commented line below the window's first lines, or the one
  // above; from the last it goes round to the first.
  const stepTalk = (way: 1 | -1) => {
    const lines = [...new Set(model.talk.map(one => one.line))].sort((one, other) => one - other)
    const here = top + 2
    const next =
      way === 1
        ? (lines.find(line => line > here) ?? lines[0])
        : ([...lines].reverse().find(line => line < here) ?? lines[lines.length - 1])

    if (next !== undefined) {
      moveTo(next - 2)
    }
  }

  const stepIssue = (by: number): void => {
    if (diags.length === 0) {
      return
    }

    const cursor = (model.cursor + by + diags.length) % diags.length
    const line = clamp(diags[cursor]?.line ?? 1, 1, lineCount)

    actions.showIssue(cursor, clamp(line - Math.floor(room / 3), 1, maxTop))
  }

  // The full text of a line's diagnostics: the card a hover floats over the
  // code, and the one the stepped-to line shows in the flow.
  const card = (here: readonly { diag: Diag; index: number }[]) =>
    here.flatMap(({ diag }) => [
      <Text color={COLOR[diag.severity]} bold>
        {MARK[diag.severity]} {diag.tool}
        {diag.rule === '' ? '' : ` ${diag.rule}`}
        {diag.isNew === undefined ? '' : diag.isNew ? ' · new' : ' · pre-existing'}
      </Text>,
      <Text>{diag.message.replace(/[ \t ]+/g, ' ')}</Text>,
    ])

  // The request's comments on this file's lines.
  const talkByLine = new Map<number, Comment[]>()

  for (const one of model.talk) {
    talkByLine.set(one.line, [...(talkByLine.get(one.line) ?? []), one])
  }

  // The search: what is typed in the find field, where it occurs, and which
  // match the person is on.
  const matches = isFinding ? findMatches(texts, model.find) : []
  const foundByLine = new Map<number, (readonly [number, number])[]>()

  for (const match of matches) {
    foundByLine.set(match.line, [...(foundByLine.get(match.line) ?? []), [match.from, match.to]])
  }

  const matchAt = matches.length === 0 ? -1 : clamp(model.findAt, 0, matches.length - 1)
  const stepMatch = (by: number): void => {
    if (matches.length === 0) {
      return
    }

    const next = (Math.max(0, matchAt) + by + matches.length) % matches.length

    actions.showMatch(next, clamp((matches[next]?.line ?? 1) - Math.floor(room / 3), 1, maxTop))
  }

  // One line of the file as elements, and how many rows they take.
  // `offset` is the row of the window the line starts on, where it is being
  // placed (not just measured): it decides which way the line's card opens.
  const codeLine = (spans: readonly Span[], n: number, offset?: number) => {
    const here = byLine.get(n) ?? []
    const first = here[0]
    const isChanged = isNewFile || changed.some(range => n >= range[0] && n <= range[1])
    const isAdded = isDiff && isChanged
    const worst = here.some(({ diag }) => diag.severity === 'error')
      ? 'error'
      : (first?.diag.severity ?? 'warning')
    // The line as it is drawn: the tokenizer's colours, corrected where the
    // language server knows what a name is; then the marks (diagnostics,
    // search matches, code that is never used); then the server's inlay
    // hints, which are not in the file and so go in last.
    const parts = withInlays(
      markSpans(
        info === undefined ? spans : applySemantic(spans, info.tokens.get(n) ?? [], info.raw[n - 1]),
        here.map(({ diag }) => [diag.col, Math.max(diag.endCol, diag.col + 1)] as const),
        foundByLine.get(n) ?? [],
        [
          ...(fadedByLine.get(n) ?? []),
          ...here.filter(({ diag }) => diag.isUnused === true).map(({ diag }) => diag),
        ].map(diag => [diag.col, Math.max(diag.endCol, diag.col + 1)] as const),
      ),
      model.isHinting ? (info?.hints.get(n) ?? []) : [],
      info?.raw[n - 1],
    )
    const length = parts.reduce((sum, part) => sum + part.text.length, 0)
    const isOpen = model.isExpanded || here.some(({ index }) => index === model.cursor)
    // The message rides on the code's own row when the code leaves it room.
    const isBeside = gutter + 2 + length + 16 <= codeColumns
    const codeRows = Math.max(1, Math.ceil((gutter + 2 + length) / codeColumns))

    // The line number is the line's handle: pressing it adds the fold that
    // starts there (or the line alone) to the prompt.
    const number = (
      <Box flexShrink={0}>
        {/* A run of lines from one commit names it on its first line only. */}
        {blame !== undefined &&
          (n > 1 && (blame[n - 1]?.hash ?? '') === (blame[n - 2]?.hash ?? '') ? (
            <Text>{' '.repeat(BLAME_WIDTH + 1)}</Text>
          ) : (blame[n - 1]?.hash ?? '') === '' ? (
            <Text dimColor>{'uncommitted'.padEnd(BLAME_WIDTH + 1)}</Text>
          ) : (
            [
              <Button
                plain
                dimColor
                key={`blame:${n}`}
                label={`${blame[n - 1]?.hash ?? ''} ${(blame[n - 1]?.author ?? '').slice(0, 8).padEnd(8)} ${(blame[n - 1]?.age ?? '').padStart(4)}`}
                // Pressing a line's blame opens its commit in the graph.
                onPress={() => actions.openCommit(blame[n - 1]?.hash ?? '')}
              />,
              <Text> </Text>,
            ]
          ))}
        <Text color="green">{isAdded ? '+' : isChanged ? '▎' : ' '}</Text>
        <Button
          plain
          dimColor
          key={`ln:${n}`}
          label={String(n).padStart(gutter)}
          onPress={() => actions.pressLine(n)}
        />
        <Text> </Text>
      </Box>
    )
    const code = (
      <Text backgroundColor={isAdded ? ADDED_BACKGROUND : undefined}>
        {parts.length === 0 ? ' ' : ''}
        {parts.map(part =>
          part.isHint ? (
            // An inlay hint is the server's aside, not the file's text.
            <Text color={part.color} italic dimColor>
              {part.text}
            </Text>
          ) : part.isFaded && !part.isMarked && !part.isFound ? (
            // Code that is never used is faded, as an editor fades it.
            <Text color={part.color === '' ? undefined : part.color} dimColor>
              {part.text}
            </Text>
          ) : part.isFound ? (
            // A search's match is lit, and keeps a diagnostic's underline.
            <Text
              color={part.isMarked ? COLOR[worst] : part.color === '' ? undefined : part.color}
              backgroundColor={FOUND_BACKGROUND}
              underline={part.isMarked}
            >
              {part.text}
            </Text>
          ) : part.isMarked ? (
            <Text color={COLOR[worst]} underline>
              {part.text}
            </Text>
          ) : part.color === '' ? (
            part.text
          ) : (
            <Text color={part.color}>{part.text}</Text>
          ),
        )}
      </Text>
    )

    // What reviewers said on this line: one cut line, or the whole thread
    // when everything is expanded.
    const talk = talkByLine.get(n) ?? []
    // They are drawn as one card under the line, a thread as a review tool
    // shows it: who and when, then what was said, replies indented. Folded,
    // the card keeps the first comment's opening lines and counts the rest.
    const talkWidth = Math.max(24, Math.min(100, codeColumns - gutter - 4))
    const talkLines: { text: string; kind: 'head' | 'body' | 'more' }[] = []

    for (const [at, one] of (model.isExpanded ? talk : talk.slice(0, 1)).entries()) {
      const indent = at === 0 ? '' : '  '
      const body = wrapText(one.body.trim(), talkWidth - 4 - indent.length)

      talkLines.push({
        kind: 'head',
        text: `${indent}${at === 0 ? COMMENT_ICON : '↳'} ${one.author} · ${one.when.slice(0, 10)}${one.isResolved === true ? ' · ✓ resolved' : ''}${one.isOutdated === true ? ' · outdated' : ''}`,
      })

      for (const line of model.isExpanded ? body : body.slice(0, TALK_FOLDED)) {
        talkLines.push({ kind: 'body', text: `${indent}${line}` })
      }

      if (!model.isExpanded && (body.length > TALK_FOLDED || talk.length > 1)) {
        talkLines.push({
          kind: 'more',
          text: `${[body.length > TALK_FOLDED ? '…' : '', talk.length > 1 ? `${talk.length - 1} ${talk.length === 2 ? 'reply' : 'replies'}` : ''].filter(part => part !== '').join(' ')} · e expands`,
        })
      }
    }

    // What can be done with the thread sits on the card's last row.
    const isSettled = talk.some(one => one.isResolved === true)
    const canSettle = talk.some(one => one.isResolved !== undefined)
    // A settled thread steps back: a dim gold in place of the comments' purple.
    const talkColor = isSettled ? RESOLVED_COLOR : COMMENT_COLOR
    const cardHeight = talk.length === 0 ? 0 : talkLines.length + 2 + (model.canComment ? 1 : 0)
    // The box a comment or a reply is typed in opens under the line it is
    // for (under the thread, when it answers one). Only Enter or its post
    // button sends anything to the forge.
    const isWriting = isCommenting && commentLine === n && Input !== undefined
    const writeHeight = isWriting ? 3 : 0
    const answered = model.replyTo === '' ? undefined : talk[0]
    const writeRows =
      isWriting && Input !== undefined
        ? [
            <Box
              marginLeft={gutter + 2}
              width={talkWidth}
              height={3}
              columnGap={2}
              borderStyle="round"
              borderColor={COMMIT_BOX}
              paddingX={1}
              overflow="hidden"
            >
              <Input
                key={`comment-text:${model.commentRound}`}
                label={answered === undefined ? `comment on line ${n}` : `reply to ${answered.author}`}
                placeholder="what to say, then Enter"
                submitLabel="post"
                autoFocus
                onInput={actions.typeComment}
                onSubmit={value => actions.postComment(value)}
              />
              <Button key="comment-post" variant="primary" label="post" onPress={() => actions.postComment()} />
              <Button key="comment-cancel" label="cancel" onPress={actions.cancelComment} />
            </Box>,
          ]
        : []
    // One element as tall as its lines and its border: the window counts the
    // card and the box by `talkHeight`.
    const talkHeight = cardHeight + writeHeight
    const talkRows =
      talk.length === 0
        ? writeRows
        : [
            <Box
              marginLeft={gutter + 2}
              width={talkWidth}
              height={cardHeight}
              flexDirection="column"
              borderStyle="round"
              borderColor={talkColor}
              paddingX={1}
              overflow="hidden"
            >
              {talkLines.map((line, at) => {
                const text = (
                  <Text
                    wrap="truncate-end"
                    color={line.kind === 'head' ? talkColor : undefined}
                    bold={line.kind === 'head'}
                    dimColor={line.kind === 'more'}
                  >
                    {line.text}
                  </Text>
                )

                // The card's first row carries its handle, as a problem's
                // does: pressed, the thread and its code go to the prompt.
                return at === 0 ? (
                  <Box height={1} columnGap={1} overflow="hidden">
                    <Button plain key={`talk:${n}`} label="↗" onPress={() => actions.sendTalk(n)} />
                    {text}
                  </Box>
                ) : (
                  text
                )
              })}
              {model.canComment && (
                <Box height={1} columnGap={3} overflow="hidden">
                  <Button plain key={`reply:${n}`} label="↩ reply" onPress={() => actions.replyOn(n)} />
                  {canSettle && (
                    <Button
                      plain
                      key={`settle:${n}`}
                      label={isSettled ? '↺ reopen' : '✓ resolve'}
                      onPress={() => actions.resolveOn(n, !isSettled)}
                    />
                  )}
                  <Button plain key={`talk-send:${n}`} label="↗ to prompt" onPress={() => actions.sendTalk(n)} />
                </Box>
              )}
            </Box>,
            ...writeRows,
          ]

    if (first === undefined) {
      return {
        rows: codeRows + talkHeight,
        elements: [
          <Box>
            {number}
            {code}
          </Box>,
          ...talkRows,
        ],
      }
    }

    // A Button takes no colour of its own, so the message stays a Text in
    // its severity's colour and the arrow before it is the handle: pressing
    // it adds the line's diagnostics, with its code, to the prompt. The
    // message is cut to fit so the arrow is never pushed off the row.
    const briefRoom = Math.max(
      8,
      isBeside ? codeColumns - gutter - length - 10 : codeColumns - gutter - 8,
    )
    // A line's message is marked NEW when the change brought any of its
    // diagnostics, and drawn dim when every one of them was already there.
    const isFresh = here.some(({ diag }) => diag.isNew === true)
    const isOld = here.every(({ diag }) => diag.isNew === false)
    const briefText = `${isFresh ? 'NEW ' : ''}${first.diag.message.split('\n')[0] ?? ''}${here.length > 1 ? `  +${here.length - 1} more` : ''}`
    const brief = (
      <Box flexShrink={0}>
        <Button plain key={`err:${n}`} label="↗" onPress={() => actions.sendIssues(n)} />
        <Text color={COLOR[worst]} dimColor={isOld} bold={isFresh}>
          {' '}
          {MARK[worst]}{' '}
          {briefText.length > briefRoom ? `${briefText.slice(0, briefRoom - 1)}…` : briefText}
        </Text>
      </Box>
    )
    const cardRows = here.reduce(
      (sum, { diag }) => sum + 1 + Math.ceil(diag.message.length / Math.max(1, cardWidth - 4)),
      2,
    )

    // The card opens above its line where the window has the rows for it,
    // and below where it has not (the first lines of the window): there it
    // would run off the top.
    const isBelow = !isOpen && offset !== undefined && offset < cardRows
    const cardBox = (place: { top: number } | { bottom: number }, scope?: string) => (
      <Box
        position="absolute"
        {...place}
        left={gutter + 2}
        width={cardWidth}
        display="none"
        hover={scope === undefined ? { display: 'flex' } : { display: 'flex', scope }}
        flexDirection="column"
        borderStyle="round"
        borderColor={COLOR[worst]}
        backgroundColor={CARD_BACKGROUND}
        paddingX={1}
      >
        {card(here)}
      </Box>
    )

    return {
      rows: codeRows + (isOpen ? cardRows : isBeside ? 0 : 1) + talkHeight,
      // A card that opens below is drawn after every row of the window, or
      // the rows under its line would be painted over it; it and its line
      // share a hover group, so the pointer on the line still reveals it.
      overlay: isBelow ? cardBox({ top: (offset ?? 0) + codeRows }, `card:${n}`) : undefined,
      elements: [
        <Box key={`line:${n}`} {...(isBelow ? { hover: { scope: `card:${n}` } } : {})}>
          {number}
          <Box flexShrink={isBeside ? 0 : 1}>{code}</Box>
          {isBeside && (
            <Box flexShrink={1} marginLeft={2}>
              {brief}
            </Box>
          )}
          {/* Above its line the card can hang off the line itself: rows are
              painted top to bottom, so nothing after it covers it there. */}
          {!isOpen && !isBelow && cardBox({ bottom: 1 })}
        </Box>,
        !isBeside && !isOpen && <Box marginLeft={gutter + 2}>{brief}</Box>,
        isOpen && (
          <Box
            marginLeft={gutter + 2}
            width={cardWidth}
            flexDirection="column"
            borderStyle="round"
            borderColor={COLOR[worst]}
            paddingX={1}
          >
            {card(here)}
          </Box>
        ),
        ...talkRows,
      ],
    }
  }

  // Only the lines the window has rows for are drawn, so the tree stays
  // small however long the file is.
  const windowRows = []
  // The cards that open below their line, drawn after the rows (see `codeLine`).
  const overlays: RenderChildren[] = []
  let used = 0
  let last = top - 1

  // In the diff view the lines the base had and the working tree dropped
  // are drawn above the line they came before, as a diff interleaves them.
  const removedRows = (before: number) => {
    const gone = isDiff ? (removed[before] ?? []) : []
    const rows = gone.slice(0, REMOVED_LINES).map(text => (
      <Box>
        <Text color="red">{`-${' '.repeat(gutter)} `}</Text>
        <Text color="#f48771" backgroundColor={REMOVED_BACKGROUND} wrap="truncate-end">
          {text === '' ? ' ' : text}
        </Text>
      </Box>
    ))

    return gone.length > REMOVED_LINES
      ? [
          ...rows,
          <Text color="red" dimColor>
            {' '.repeat(gutter + 2)}… {gone.length - REMOVED_LINES} more removed lines
          </Text>,
        ]
      : rows
  }

  // The window stops once the file's last line reaches its bottom row:
  // walking up from the end, `maxTop` is the first line of the last full
  // window, counting the rows each line and its diagnostics really take.
  maxTop = Math.max(1, lineCount)

  if (lines !== undefined) {
    const rowsOf = (n: number): number =>
      codeLine(lines[n - 1] ?? [], n).rows + removedRows(n).length
    // The last line always shows, with what was removed after it.
    let filled = removedRows(lineCount + 1).length + rowsOf(maxTop)

    while (maxTop > 1 && filled + rowsOf(maxTop - 1) <= room) {
      filled += rowsOf(maxTop - 1)
      maxTop -= 1
    }
  }

  top = Math.min(top, maxTop)
  last = top - 1

  while (lines !== undefined && last < lineCount && used < room) {
    last += 1
    const gone = removedRows(last)
    const drawn = codeLine(lines[last - 1] ?? [], last, used + gone.length)
    used += gone.length + drawn.rows
    windowRows.push(...gone, ...drawn.elements)

    if (drawn.overlay !== undefined) {
      overlays.push(drawn.overlay)
    }
  }

  // Lines removed from the end of the file come before a line it no longer has.
  if (lines !== undefined && last === lineCount) {
    windowRows.push(...removedRows(lineCount + 1))
  }

  // The next place the file differs from the base, below the window's top.
  const nextChange = (): number | undefined =>
    [...changed.map(range => range[0]), ...Object.keys(removed).map(Number)]
      .sort((a, b) => a - b)
      .find(line => line > top + 2)

  const minimap =
    hasMinimap && lines !== undefined
      ? minimapCells(
          lines.map((spans, at): MiniLine => {
            const text = spans.map(span => span[1]).join('')
            const here = byLine.get(at + 1) ?? []

            return {
              indent: text.length - text.trimStart().length,
              length: text.trimEnd().length,
              mark:
                here.length === 0 ? 0 : here.some(({ diag }) => diag.severity === 'error') ? 2 : 1,
              isChanged: changed.some(range => at + 1 >= range[0] && at + 1 <= range[1]),
              isTalked: talkByLine.has(at + 1),
              isSettled: (talkByLine.get(at + 1) ?? []).some(one => one.isResolved === true),
              head: heads.get(at + 1) ?? 0,
            }
          }),
          MINIMAP_COLUMNS,
          Math.min(room, MINIMAP_ROWS),
          top,
          last - top + 1,
        )
      : undefined

  // The breadcrumb: the file's path, a folder at a time, then the class and
  // function around the top of the window. Pressing a part opens a list
  // under it: a folder's own entries, or the names beside that one.
  const pathParts = file.startsWith('/') ? [file] : file.split('/')
  const around = info === undefined ? [] : enclosing(info.items, top)
  let crumbOffset = 0
  // Each part wears its icon in its colour (a folder's, a file type's, a
  // name's kind); the label is the Button, which takes no colour itself.
  const crumbPart = (
    glyph: string,
    color: string,
    label: string,
    key: string,
    press: (left: number) => void,
  ) => {
    const left = crumbOffset

    crumbOffset += label.length + 5

    // One box per part, which does not shrink: a part stays whole, and
    // wraps to the next line as a whole.
    return (
      <Box flexShrink={0}>
        <Text color={color === '' ? undefined : color}>{glyph} </Text>
        <Button plain key={key} label={label} onPress={() => press(left % columns)} />
        <Text dimColor> › </Text>
      </Box>
    )
  }
  const trail = [
    ...pathParts.flatMap((part, at) => {
      const isFile = at === pathParts.length - 1
      const icon = iconOf(file)

      return crumbPart(
        isFile ? icon.glyph : '\u{f07b}',
        isFile ? icon.color : '#dcb67a',
        part,
        `crumb:${at}`,
        left => actions.toggleFolder(pathParts.slice(0, at).join('/'), left),
      )
    }),
    ...around.flatMap((item, at) =>
      crumbPart(
        outlineRows([item])[0]?.label.trimStart().charAt(0) ?? '·',
        kindColor(item.kind),
        item.name,
        `crumb-in:${at}`,
        left => actions.toggleNames(at, left),
      ),
    ),
    info !== undefined && (
      <Button
        plain
        dimColor
        key="crumb-more"
        label="…"
        onPress={() => actions.toggleNames(around.length, crumbOffset)}
      />
    ),
  ]

  // What the open part lists. A folder lists what it holds, folders first,
  // with a way up; a name lists the names beside it in the outline.
  type Entry = { label: string; glyph: string; color: string; isHere: boolean; press: () => void }
  let entries: Entry[] = []

  if (crumb.kind === 'dir' && model.folder !== undefined && model.folder.dir === crumb.dir) {
    const within = crumb.dir === '' ? '' : `${crumb.dir}/`

    entries = [
      ...(crumb.dir === ''
        ? []
        : [
            {
              label: '..',
              glyph: '\u{f07c}',
              color: '#dcb67a',
              isHere: false,
              press: () =>
                actions.listFolder(
                  crumb.dir.includes('/') ? crumb.dir.slice(0, crumb.dir.lastIndexOf('/')) : '',
                  crumb.left,
                ),
            },
          ]),
      ...model.folder.entries.map((name): Entry => {
        const isFolder = name.endsWith('/')
        const full = `${within}${name.replace(/\/$/, '')}`
        const icon = iconOf(full)

        return {
          label: name,
          glyph: isFolder ? '\u{f07b}' : icon.glyph,
          color: isFolder ? '#dcb67a' : icon.color,
          isHere: file === full || file.startsWith(`${full}/`),
          press: () => (isFolder ? actions.listFolder(full, crumb.left) : actions.openFile(full, 1)),
        }
      }),
    ]
  } else if (crumb.kind === 'symbol' && info !== undefined) {
    const parent = crumb.level === 0 ? undefined : around[crumb.level - 1]

    entries = outlineRows(
      info.items.filter(item =>
        parent === undefined
          ? item.depth === 0
          : item.depth === parent.depth + 1 && item.line >= parent.line && item.line <= parent.endLine,
      ),
    ).map(({ item, label }) => ({
      label: item.name,
      glyph: label.trimStart().charAt(0),
      color: kindColor(item.kind),
      isHere: around[crumb.level] === item,
      press: () => actions.jumpTo(clamp(item.line, 1, maxTop)),
    }))
  }

  // The list takes the room there is: as wide as its longest entry needs,
  // up to the pane's width, and as tall as the window under it allows.
  const crumbRows = clamp(room - 3, 6, 30)
  const crumbWidth = clamp(
    Math.max(CRUMB_WIDTH, ...entries.map(entry => entry.label.length + 14)),
    CRUMB_WIDTH,
    columns - 2,
  )
  // It opens on the entry the file is at, and the wheel moves it.
  const hereAt = entries.findIndex(entry => entry.isHere)
  const crumbTop = clamp(
    crumb.top < 0 ? hereAt - Math.floor(crumbRows / 2) : crumb.top,
    0,
    entries.length - crumbRows,
  )

  return {
    window: {
      maxTop,
      // Where the popover sits among the pane's rows: under the status and
      // the breadcrumb, inside the comparison border if any.
      crumbBox:
        entries.length === 0
          ? undefined
          : {
              from: shell.inset / 2 + 1 + crumbLines,
              to: shell.inset / 2 + 2 + crumbLines + Math.min(entries.length, crumbRows) + 1,
              top: crumbTop,
              max: Math.max(0, entries.length - crumbRows),
            },
    },
    tree: (
      <Box flexDirection="column">
        {statusLine(kit, shell)}
        {/* The breadcrumb takes the lines its path needs, up to three: a part
            is never squeezed, and what does not fit on a line goes to the next. */}
        <Box height={crumbLines} overflow="hidden" flexWrap="wrap">
          {trail}
        </Box>
        {/* The keys used all the time stay on one row; the rest open in a box
            under it (a), so the header is not a wall of them. A key works
            while its button is drawn, so the box is where the others live. */}
        <Box columnGap={2} flexWrap="wrap">
          <Button plain key="back" hotkey="b" label="back" onPress={actions.back} />
          <Button plain key="next" hotkey="n" label="next issue" onPress={() => stepIssue(1)} />
          <Button plain key="prev" hotkey="p" label="prev issue" onPress={() => stepIssue(-1)} />
          <Button
            plain
            key="down"
            hotkey="d"
            label="down"
            onPress={() => moveTo(top + Math.floor(room / 2))}
          />
          <Button
            plain
            key="up"
            hotkey="u"
            label="up"
            onPress={() => moveTo(top - Math.floor(room / 2))}
          />
          <Button
            plain
            key="diff"
            hotkey="v"
            label={isDiff ? 'file view' : 'diff view'}
            onPress={actions.toggleDiff}
          />
          <Button plain key="find" hotkey="f" label="find" onPress={actions.find} />
          {/* A markdown file's way back to how it reads is always at hand. */}
          {isMarkdownFile(file) && (
            <Button plain key="rendered" hotkey="m" label="rendered" onPress={actions.showRendered} />
          )}
          <Button
            plain
            key="more"
            hotkey="a"
            label={isMore ? 'less' : 'more…'}
            onPress={actions.toggleMore}
          />
          {helpButton(kit, actions.help)}
        </Box>
        {isMore && (
          <Box
            columnGap={2}
            flexWrap="wrap"
            borderStyle="round"
            borderDimColor
            paddingX={1}
          >
            <Button plain key="top" hotkey="g" label="top" onPress={() => moveTo(1)} />
            <Button
              plain
              key="expand"
              hotkey="e"
              label={model.isExpanded ? 'collapse' : 'expand'}
              onPress={actions.toggleExpanded}
            />
            <Button
              plain
              key="change"
              hotkey="c"
              label="next change"
              onPress={() => {
                const line = nextChange()

                actions.nextChange(line === undefined ? undefined : clamp(line - 2, 1, maxTop))
              }}
            />
            <Button
              plain
              key="blame"
              hotkey="l"
              label={blame === undefined ? 'blame' : 'hide blame'}
              onPress={actions.toggleBlame}
            />
            {commit === '' && (
              <Button
                plain
                key="inspect"
                hotkey="t"
                label="look up selection"
                onPress={() => actions.lookUpSelection(top, last)}
              />
            )}
            {commit === '' && (
              <Button
                plain
                key="hints"
                hotkey="i"
                label={model.isHinting ? 'hide hints' : 'inlay hints'}
                onPress={actions.toggleHints}
              />
            )}
            <Button
              plain
              key="selection"
              hotkey="s"
              label="selection to prompt"
              onPress={actions.sendSelection}
            />
            {model.canComment && (
              <Button
                plain
                key="comment"
                hotkey="o"
                label={isCommenting ? 'stop commenting' : 'comment'}
                onPress={actions.toggleCommenting}
              />
            )}
            {model.canComment && (
              <Button plain key="talk-next" hotkey="w" label="next comment" onPress={() => stepTalk(1)} />
            )}
            {model.canComment && (
              <Button plain key="talk-prev" hotkey="q" label="prev comment" onPress={() => stepTalk(-1)} />
            )}
            {model.canComment && (
              <Button
                plain
                key="talk-resolved"
                hotkey="z"
                label={model.hidesResolved ? 'show resolved' : 'hide resolved'}
                onPress={actions.toggleResolved}
              />
            )}
            {model.canComment && (
              <Button plain key="talk-all" hotkey="y" label="all threads" onPress={actions.listThreads} />
            )}
            <Button plain key="refresh" hotkey="r" label="refresh" onPress={actions.refresh} />
          </Box>
        )}
        {notesOf(kit, shell.notes)}
        {model.note !== '' && (
          <Text color="yellow" wrap="truncate-end">
            ! {model.note}
          </Text>
        )}
        <Text bold wrap="truncate-end">
          {model.isChecked ? countLabel(diags) || '✓' : ''}
          {lineCount > 0 ? `  ${top}–${last} of ${lineCount}` : ''}
          {commit === '' ? '' : `  @ ${commit}`}
          {isDiff ? '  · diff' : ''}
        </Text>
        {/* The looked-up name: what it is, and a way to where it is defined. */}
        {symbol !== undefined && (
          <Box flexDirection="column" borderStyle="round" borderColor="cyan" paddingX={1}>
            <Text bold color="cyan" wrap="truncate-end">
              {symbol.name}
            </Text>
            {symbolLines.map(text => (
              <Box height={1} overflow="hidden">
                <Text>{text === '' ? ' ' : text}</Text>
              </Box>
            ))}
            {/* The call the name sits in, the argument being given in brackets. */}
            {symbol.signature !== '' && (
              <Box height={1} overflow="hidden">
                <Text dimColor>in a call: {symbol.signature}</Text>
              </Box>
            )}
            {/* Where it is declared, and where its type is. */}
            <Box columnGap={2} height={1} overflow="hidden">
              {symbol.path !== '' && (
                <Button
                  key="symbol-go"
                  variant="primary"
                  label={`definition: ${symbol.path.split('/').slice(-2).join('/')}:${symbol.line}`}
                  onPress={() => actions.openFile(symbol.path, symbol.line)}
                />
              )}
              {symbol.typePath !== '' && (
                <Button
                  key="symbol-type"
                  label={`its type: ${symbol.typePath.split('/').slice(-2).join('/')}:${symbol.typeLine}`}
                  onPress={() => actions.openFile(symbol.typePath, symbol.typeLine)}
                />
              )}
              {symbol.path === '' && symbol.typePath === '' && (
                <Text dimColor>The server does not say where it is defined.</Text>
              )}
            </Box>
            {/* Where it reaches: each of these opens a list to jump from. */}
            <Box columnGap={2} height={1} overflow="hidden">
              <Button key="symbol-uses" label="uses" onPress={actions.listUses} />
              <Button key="symbol-callers" label="callers" onPress={actions.listCallers} />
              <Button key="symbol-callees" label="what it calls" onPress={actions.listCallees} />
              {symbol.hasImplementations && (
                <Button
                  key="symbol-implementations"
                  label="implementations"
                  onPress={actions.listImplementations}
                />
              )}
              <Button key="symbol-close" label="close" onPress={actions.closeLookup} />
            </Box>
          </Box>
        )}
        {/* The comment row: a line number picks the line, and only Enter or
            the post button sends anything to the forge. */}
        {isCommenting && Input !== undefined && (
          <Box height={1} overflow="hidden">
            <Text color={COMMENT_COLOR} wrap="truncate-end">
              {COMMENT_ICON}{' '}
              {commentLine === 0
                ? 'Commenting: press a line number to write on that line, or reply on a thread.'
                : `Writing on line ${commentLine}: Enter posts it. Press another line number to move the box.`}
            </Text>
          </Box>
        )}
        {/* The find row: typing narrows the matches, Enter goes to the next. */}
        {/* The field keeps its own text: what is typed is not drawn back into
            it, which would race the typing and drop keys. While it has the
            keyboard every key is text, so Enter also hands the keyboard to
            the buttons beside it, where the pane's keys work again. */}
        {isFinding && Input !== undefined && (
          <Box
            columnGap={2}
            height={3}
            overflow="hidden"
            borderStyle="round"
            borderColor={COMMIT_BOX}
            paddingX={1}
          >
            <Input
              key="find-text"
              label="find"
              placeholder="text in this file, then Enter"
              submitLabel="go"
              autoFocus
              onInput={actions.typeFind}
              onSubmit={() => {
                stepMatch(1)
                actions.leaveFindField()
              }}
            />
            <Text dimColor>
              {model.find === ''
                ? ''
                : matches.length === 0
                  ? 'no matches'
                  : `${matchAt + 1} of ${matches.length}`}
            </Text>
            <Button plain key="find-next" hotkey="j" label="next" onPress={() => stepMatch(1)} />
            <Button plain key="find-prev" hotkey="k" label="prev" onPress={() => stepMatch(-1)} />
            <Button plain key="find-close" hotkey="x" label="close find" onPress={actions.closeFind} />
          </Box>
        )}
        {/* The diff's key: which side each mark belongs to. */}
        {isDiff && (
          <Box columnGap={2}>
            <Text color="red">
              − removed ·{' '}
              {!model.isChecked
                ? `${shortRef(commit)}^`
                : model.diffAgainst !== ''
                  ? model.diffAgainst
                  : shell.isComparing
                    ? shell.against
                    : 'your last commit'}
            </Text>
            <Text color="green">+ added · {commit !== '' ? shortRef(commit) : shell.headName}</Text>
          </Box>
        )}
        {lines === undefined && <Text dimColor>Loading…</Text>}
        <Box height={room} overflow="hidden">
          <Box flexDirection="column" width={codeColumns + blameWidth} overflow="hidden">
            {windowRows}
            {overlays}
          </Box>
          {Raster !== undefined && minimap !== undefined && (
            <Box marginLeft={1}>
              <Raster key="minimap" columns={MINIMAP_COLUMNS} rows={Math.min(room, MINIMAP_ROWS)} cells={minimap} />
            </Box>
          )}
        </Box>
        {/* The breadcrumb's popover: drawn last, so it paints over the rows
            under the breadcrumb and moves none of them. */}
        {entries.length > 0 && (
          <Box
            position="absolute"
            top={1 + crumbLines}
            left={clamp(crumb.left, 0, columns - crumbWidth)}
            width={crumbWidth}
            flexDirection="column"
            borderStyle="round"
            borderColor={COMMIT_BOX}
            backgroundColor={CARD_BACKGROUND}
          >
            {entries.slice(crumbTop, crumbTop + crumbRows).map((entry, at) => (
              <Box height={1} overflow="hidden" backgroundColor={CARD_BACKGROUND}>
                <Text color={entry.color === '' ? undefined : entry.color}>
                  {' '}
                  {entry.glyph}{' '}
                </Text>
                <Button
                  plain
                  key={`crumb-row:${crumbTop + at}`}
                  label={entry.label.slice(0, crumbWidth - 12)}
                  onPress={entry.press}
                />
                {entry.isHere && <Text color={COMMIT_BOX}> ◂ here</Text>}
              </Box>
            ))}
            <Box columnGap={2} height={1} overflow="hidden" backgroundColor={CARD_BACKGROUND}>
              <Text dimColor>
                {' '}
                {crumbTop + 1}–{Math.min(entries.length, crumbTop + crumbRows)} of {entries.length}
              </Text>
              {entries.length > crumbRows && <Text dimColor>wheel to scroll</Text>}
              <Button plain key="crumb-close" label="close" onPress={actions.closeCrumb} />
            </Box>
          </Box>
        )}
      </Box>
    ),
  }
}

files.hooks/screens/frame.tsx:
// What every screen shares: the elements a screen is drawn with, the line
// that says what is under review, the frame round a screen, and the few
// colours and marks more than one screen uses.
//
// A screen is a pure view: it takes these elements, a model of plain data
// and its actions (what a person can do there, as closures), and returns the
// tree to draw. It never sees the engine's handle.

import type { ElementTable, Elements, RenderChildren } from 'claude-code'

import type { Severity } from '../../types'
import type { Comment } from '../review'

// The elements of the surface the pane is on. Every surface has the first
// three; a screen draws without the others where a surface lacks them.
export type Kit = {
  Box: Elements['terminal']['Box']
  Text: Elements['terminal']['Text']
  Button: Elements['terminal']['Button']
  Input: Elements['terminal']['Input'] | undefined
  Markdown: Elements['terminal']['Markdown'] | undefined
  Raster: Elements['terminal']['Raster'] | undefined
  Link: Elements['terminal']['Link'] | undefined
}

export const kitOf = (table: ElementTable): Kit => ({
  Box: table.Box,
  Text: table.Text,
  Button: table.Button,
  Input: 'Input' in table ? table.Input : undefined,
  Markdown: 'Markdown' in table ? table.Markdown : undefined,
  Raster: 'Raster' in table ? table.Raster : undefined,
  Link: 'Link' in table ? table.Link : undefined,
})

// The changed files in one row of numbers: lines added and deleted across
// them, and the errors and other problems found in them. `fresh` is how many
// of those the change brought, where that is known.
export type Totals = {
  files: number
  added: number
  deleted: number
  errors: number
  others: number
  fresh: number | undefined
}

// What every screen says of the review itself, and the room it has.
export type Shell = {
  // The cells and rows a screen has to itself, inside the side padding and,
  // while a comparison is on, its border; `inset` is what that border takes
  // of each (2, or 0).
  columns: number
  rows: number
  inset: number
  // The cells left clear at each side of the screen (a setting).
  padding: number
  // The folder under review, by its own name.
  repoName: string
  // The repo the folder under review is a worktree of, by name; '' when it
  // is the repo's main checkout (or its only one).
  worktreeOf: string
  // What is checked out, by branch name where there is one.
  headName: string
  // The side the comparison is read from (the target, or what is checked
  // out) and what it is read against, by a branch's name where it has one.
  side: string
  against: string
  // The pull or merge request under review, as a label; '' for none.
  request: string
  // The request whose comments the pane shows, by name ("PR #12"): the one
  // under review, or the open one of the branch checked out. '' for none.
  reviewing: string
  // Whether anything but the uncommitted changes is being compared.
  isComparing: boolean
  // While a scan runs: the mark that turns, and the tools still out.
  isScanning: boolean
  busyMark: string
  pending: readonly string[]
  // How many of the files to check have been, while they go in batches.
  checked: number
  toCheck: number
  // What else the pane is waiting on, in a few words ('' for nothing): the
  // language server reading the open file.
  working: string
  isProjectChecked: boolean
  // What a scan could not do, a line each.
  notes: readonly string[]
  totals: Totals
}

export const COLOR: Record<Severity, string> = { error: 'red', warning: 'yellow', info: 'cyan' }
export const MARK: Record<Severity, string> = { error: '✖', warning: '⚠', info: 'ℹ' }
// git's one-letter status as a word, in the colour VS Code gives it.
export const STATUS_WORD: Record<string, [word: string, color: string]> = {
  M: ['modified', '#e2c08d'],
  A: ['added', '#73c991'],
  D: ['deleted', '#f14c4c'],
  R: ['renamed', '#73c991'],
  T: ['type changed', '#e2c08d'],
  '?': ['new', '#73c991'],
}
export const CARD_BACKGROUND = '#1f1f1f'
// A worktree's mark and colour, on the graph's badges and the first line.
export const WORKTREE_ICON = '\u{f07c}'
export const WORKTREE_COLOR = '#4ec9b0'
export const COMMIT_BOX = '#3794ff'
export const STASH_ICON = '\u{f187}'
export const STASH_COLOR = '#a371f7'
// A request's review comments: their mark and their colour.
export const COMMENT_ICON = '\u{f075}'
export const COMMENT_COLOR = '#c586c0'
// The forges' own marks, and GitLab's own colour.
export const GITHUB_ICON = '\u{f09b}'
export const GITLAB_ICON = '\u{f296}'
export const GITLAB_COLOR = '#fc6d26'
// The colour of a review thread that has been resolved.
export const RESOLVED_COLOR = '#9a8444'
// How many lines of a commit's body show at once.
export const BODY_ROWS = 12
// The most files listed under a commit or a stash.
export const COMMIT_FILES = 40
// The border drawn round every screen while a comparison is on.
const COMPARE_COLOR = '#ffab40'

// A review comment in one line: who said it, what, and whether it is settled.
export const said = (one: Comment): string =>
  `${one.author}: ${one.body.replace(/\s+/g, ' ')}${one.isResolved === true ? '  ✓ resolved' : ''}`

// The first line of every screen: the folder, what is compared, and while a
// scan runs, what it is waiting on.
export const statusLine = ({ Text }: Kit, shell: Shell) => (
  <Text dimColor wrap="truncate-end">
    {/* A worktree says so first and in colour: its files are not the main
        checkout's, which is easy to forget once inside it. */}
    {shell.worktreeOf === '' ? (
      ''
    ) : (
      <Text color={WORKTREE_COLOR} dimColor={false} bold>
        {WORKTREE_ICON} worktree of {shell.worktreeOf} ·{' '}
      </Text>
    )}
    {shell.repoName} · {shell.request === '' ? shell.side : shell.request}
    {shell.request !== ''
      ? ''
      : shell.isComparing
        ? ` vs ${shell.against}`
        : ' · uncommitted changes'}
    {shell.request === '' && shell.reviewing !== '' ? ` · ${shell.reviewing}` : ''}
    {shell.isScanning
      ? ` · ${shell.busyMark} ${shell.pending.length === 0 ? 'reading changes' : `checking: ${shell.pending.join(', ')}`}`
      : ''}
    {shell.isScanning && shell.toCheck > shell.checked && shell.checked > 0
      ? ` · ${shell.checked} of ${shell.toCheck} files checked`
      : ''}
    {shell.working === '' ? '' : ` · ${shell.working}`}
    {shell.isProjectChecked ? ' · whole project checked' : ''}
  </Text>
)

export const notesOf = ({ Text }: Kit, notes: readonly string[]) =>
  notes.map(note => (
    <Text color="yellow" wrap="truncate-end">
      ! {note}
    </Text>
  ))

// Every screen has `h`: the keys that work on it, and what the marks mean.
export const helpButton = ({ Button }: Kit, onPress: () => void) => (
  <Button plain key="help" hotkey="h" label="keys" onPress={onPress} />
)

// The frame round a screen. While a comparison is on, every screen is drawn
// inside a bright border, so it cannot be mistaken for the plain view of the
// working tree. Every screen also keeps a little air on each side, so its
// text does not sit against the pane's own edge (or the comparison border).
//
// A screen that draws its own window (`isOwn`: the file, the graph) is as
// tall as the pane, which leaves the pane nothing to scroll, and its scroll
// keys (the arrows, page up and down) are only raised while it has rows to
// scroll. So such a screen gets a blank row above it and a few below, and
// the pane is to be held one row down (the `pin` key, which the hooks
// module's timer scrolls to): there is then always a row either way, the
// keys always raise `ui.scroll`, and the scroll hook turns them into moves
// of the screen's window.
export const frame = (
  { Box, Text }: Kit,
  isComparing: boolean,
  padding: number,
  screen: RenderChildren,
  isOwn = false,
) => {
  const framed = isComparing ? (
    <Box
      key="pin"
      flexDirection="column"
      borderStyle="round"
      borderColor={COMPARE_COLOR}
      paddingX={padding}
    >
      {screen}
    </Box>
  ) : (
    <Box key="pin" flexDirection="column" paddingX={padding}>
      {screen}
    </Box>
  )

  if (!isOwn) {
    return framed
  }

  return (
    <Box flexDirection="column">
      <Text> </Text>
      {framed}
      <Text> </Text>
      <Text> </Text>
      <Text> </Text>
    </Box>
  )
}

files.hooks/screens/graph.tsx:
// The git graph: the whole history in lanes, with what an opened commit or
// stash holds under its row, and the panel that starts a comparison.
//
// The graph draws its own window over the history, as the file screen does
// over a file: every line is exactly one row tall, so the window knows which
// line sits on which row, the pane's own scroll stays put, and only the
// lines in view are ever drawn.

import type { RenderChildren } from 'claude-code'

import type { GraphRow, Picked, Span, Worktree } from '../../types'
import type { Stash } from '../git'
import { GRAPH_COMMITS, UNCOMMITTED, laneColor } from '../git'
import { clamp, wrapText } from '../text'
import { iconOf } from '../tree'
import type { Kit, Shell } from './frame'
import {
  BODY_ROWS,
  COMMIT_BOX,
  COMMIT_FILES,
  STASH_COLOR,
  STASH_ICON,
  STATUS_WORD,
  WORKTREE_COLOR,
  WORKTREE_ICON,
  helpButton,
  statusLine,
} from './frame'

// Nerd Font glyphs for the graph's badges, and the ground a name is set on.
const BRANCH_ICON = '\u{e725}'
const TAG_ICON = '\u{f02b}'
const BADGE_GROUND = '#2d333b'
// The longest a branch's name is drawn on a graph row before it is cut.
const BADGE_NAME = 18
// The compare panel: how many names it offers under its fields, and the rows
// it takes in all (its border, two fields, a caption, the offers, a gap, the
// buttons), fixed so the graph's window knows what is left.
const PICK_OFFERS = 6
const PICK_ROWS = PICK_OFFERS + 7

export type GraphModel = {
  shell: Shell
  // The history, the uncommitted row first; and the stashes, each hung under
  // the commit it was made on.
  rows: readonly GraphRow[]
  stashes: readonly Stash[]
  // The repo's worktrees: each other one is a badge on the commit it has
  // checked out, pressed to review it there.
  worktrees: readonly Worktree[]
  // The repo's open pull or merge requests, once the forge has listed them.
  requests: readonly { typed: string; title: string }[]
  // The local branches, the one checked out ("HEAD" when detached) and its
  // commit's short hash.
  branches: readonly string[]
  head: string
  headHash: string
  // What the comparison is against, and whether it is between two commits
  // (what is checked out then plays no part, and cannot be undone from here).
  base: string
  hasTarget: boolean
  // The commit or stash opened ('' for none), what it holds once that is
  // read, and the first line of its body in view.
  selected: string
  picked: Picked
  bodyTop: number
  // The first line of the window, 0-based.
  top: number
  // Whether undoing the last commit is being confirmed, and what is known
  // about that commit being pushed.
  isUndoing: boolean
  undoNote: string
  // The compare panel: whether it is open, what its two fields hold, and
  // which of them the offers are for.
  isPicking: boolean
  pickA: string
  pickB: string
  pickField: 'a' | 'b'
}

export type GraphActions = {
  // Returns to where the graph was opened from.
  back: () => void
  help: () => void
  refresh: () => void
  // Moves the window so `line` is its first.
  scrollTo: (line: number) => void
  // Opens a commit or a stash under its row, or closes the one that is open.
  open: (id: string) => void
  // Opens a file as that commit or stash left it.
  openFile: (id: string, path: string) => void
  applyStash: (ref: string) => void
  popStash: (ref: string) => void
  // Compares what is checked out with a commit.
  compareWith: (hash: string) => void
  checkOutBranch: (name: string) => void
  checkOutCommit: (hash: string) => void
  // Undoing the last commit: asked for, confirmed, or called off.
  askUndo: () => void
  undo: () => void
  keepCommit: () => void
  // The compare panel: opened (on the comparison in force) or closed, called
  // off, typed in, an offer taken in place of typing, and the comparison of
  // what the two fields name started.
  toggleCompare: () => void
  cancelCompare: () => void
  typeCompare: (field: 'a' | 'b', text: string) => void
  takeOffer: (value: string) => void
  // Reviews another worktree of the repo.
  switchWorktree: (path: string) => void
  compare: (side: string, against: string) => void
}

// The window as drawn, for the scroll hook: how many rows the header takes,
// the kind of line on each row under it, the furthest the first line may go
// (where the last line sits on the bottom row), and how far the opened
// commit's body can scroll.
export type GraphWindow = {
  header: number
  kinds: ('row' | 'body')[]
  maxTop: number
  bodyMax: number
}

export const graphScreen = (
  kit: Kit,
  model: GraphModel,
  actions: GraphActions,
): { tree: RenderChildren; window: GraphWindow } => {
  const { Box, Button, Text, Input } = kit
  const { shell, rows: graphRows, stashes, branches, head, headHash, base, selected } = model
  const { picked: chosen, isPicking, pickA, pickB, pickField } = model
  const { totals } = shell
  const graphWidth = Math.max(2, ...graphRows.slice(0, 400).map(row => row.width))
  const inGraph = new Set(graphRows.map(row => row.hash))
  const columns = shell.columns
  // What is left of a row beside the lanes, for text that must not wrap.
  const textRoom = Math.max(12, columns - (graphWidth + 1) - 2)
  const cut = (text: string, room: number): string =>
    text.length > room ? `${text.slice(0, Math.max(1, room - 1))}…` : text

  const lanesOf = (cells: readonly Span[]) => (
    <Box flexShrink={0} width={graphWidth + 1}>
      <Text>
        {cells.map(cell => (cell[0] === '' ? cell[1] : <Text color={cell[0]}>{cell[1]}</Text>))}
      </Text>
    </Box>
  )
  // One row of the window: the lanes, then what the row says, clipped to
  // a single row whatever its width.
  const rowOf = (cells: readonly Span[], rest: RenderChildren) => (
    <Box height={1} overflow="hidden">
      {lanesOf(cells)}
      {rest}
    </Box>
  )
  const lines: { kind: 'row' | 'body'; draw: () => ReturnType<typeof rowOf> }[] = []
  const add = (
    cells: readonly Span[],
    rest: () => RenderChildren,
    kind: 'row' | 'body' = 'row',
  ) =>
    lines.push({ kind, draw: () => rowOf(cells, rest()) })

  const detailText = wrapText(chosen.subject, textRoom)
  const detailBody = wrapText(chosen.body, textRoom - 2)
  const detailTop = clamp(model.bodyTop, 0, detailBody.length - BODY_ROWS)

  // What an opened commit or stash holds, a line each, with the lanes
  // still running down beside it: its whole subject, its body in a window
  // of its own, what can be done with it, and the files it changed.
  const details = (id: string, cells: readonly Span[], offered: (() => RenderChildren)[]) => {
    if (selected !== id) {
      return
    }

    if (chosen.hash !== id) {
      add(cells, () => <Text dimColor>Loading…</Text>)

      return
    }

    for (const text of detailText) {
      add(cells, () => <Text bold>{text}</Text>)
    }

    for (const text of detailBody.slice(detailTop, detailTop + BODY_ROWS)) {
      add(
        cells,
        () => (
          <Text italic dimColor>
            ▏ {text}
          </Text>
        ),
        'body',
      )
    }

    if (detailBody.length > BODY_ROWS) {
      add(
        cells,
        () => (
          <Text dimColor>
            ▏ lines {detailTop + 1}–{Math.min(detailBody.length, detailTop + BODY_ROWS)} of{' '}
            {detailBody.length} · scroll here for the rest
          </Text>
        ),
        'body',
      )
    }

    for (const offer of offered) {
      add(cells, offer)
    }

    if (chosen.files.length === 0) {
      add(cells, () => <Text dimColor>No files changed here.</Text>)
    }

    for (const one of chosen.files.slice(0, COMMIT_FILES)) {
      const icon = iconOf(one.path)
      const stat = chosen.stats[one.path]
      const change = STATUS_WORD[one.status]

      add(cells, () => [
        <Text color={icon.color}>{icon.glyph} </Text>,
        <Button
          plain
          key={`changed:${id}:${one.path}`}
          label={cut(one.path, textRoom - 26)}
          onPress={() => actions.openFile(id, one.path)}
        />,
        change !== undefined && <Text color={change[1]}>  {change[0]}</Text>,
        stat !== undefined && <Text color="green">  +{stat[0]}</Text>,
        stat !== undefined && <Text color="red"> −{stat[1]}</Text>,
      ])
    }

    if (chosen.files.length > COMMIT_FILES) {
      add(cells, () => (
        <Text dimColor>… {chosen.files.length - COMMIT_FILES} more files</Text>
      ))
    }
  }

  const stashLines = (one: Stash, cells: readonly Span[], isAdrift: boolean) => {
    const trail = `${isAdrift && one.base ? `on ${one.base} · ` : ''}${(one.when ?? '').replace(' ago', '')}`

    add(cells, () => [
      <Text backgroundColor={STASH_COLOR} color="#000000">
        {' '}
        {STASH_ICON}{' '}
      </Text>,
      <Text> </Text>,
      <Button plain key={`stash:${one.ref}`} label={one.ref} onPress={() => actions.open(one.ref)} />,
      <Text dimColor>
        {' '}
        {cut(one.subject, textRoom - one.ref.length - trail.length - 20)} {trail}{' '}
      </Text>,
      <Button
        plain
        key={`apply:${one.ref}`}
        label="apply"
        onPress={() => actions.applyStash(one.ref)}
      />,
      <Text> </Text>,
      <Button plain key={`pop:${one.ref}`} label="pop" onPress={() => actions.popStash(one.ref)} />,
    ])
    details(one.ref, cells, [])
  }

  for (const row of graphRows) {
    const below = row.below ?? []

    // What is not committed yet sits in its own lane, joined to the
    // commit checked out; its dot is hollow, there being no commit there.
    if (row.hash === UNCOMMITTED) {
      add(
        row.cells.map((cell): Span => [cell[0], cell[1].replace('●', '○')]),
        () => [
          <Text dimColor>Uncommitted changes ({totals.files}) </Text>,
          <Text color="green">+{totals.added} </Text>,
          <Text color="red">−{totals.deleted} </Text>,
          <Text color="red">{totals.errors}✖ </Text>,
          <Text color="yellow">{totals.others}⚠</Text>,
        ],
      )

      if (below.some(cell => cell[0] !== '')) {
        add(below, () => undefined)
      }

      continue
    }

    const trail = `${row.when.replace(' ago', '')} · ${row.author.split(' ')[0] ?? ''} ${row.hash}`
    const names = row.refs.map(ref => ref.replace(/^HEAD -> /, '').replace(/^tag: /, ''))
    // The badges may take under half the row, so the title always has room
    // to be read and pressed: a long name is cut, and the badges that do
    // not fit are counted in one last badge. Each costs three cells of
    // icon, the name with a space each side, and a gap. The opened commit
    // lists every name in full.
    let badgeRoom = Math.floor(textRoom * 0.45)
    const worn: { ref: string; name: string }[] = []
    // A branch and a remote's copy of it on the same commit share one badge,
    // the remote named after it ("main | origin"): the copy has no badge of
    // its own. A name is a remote's copy when it is no local branch and what
    // follows its first slash is one on this row.
    const onRow = new Set(names)
    const isCopy = (name: string): boolean =>
      name.includes('/') &&
      !model.branches.includes(name) &&
      onRow.has(name.slice(name.indexOf('/') + 1))
    const merged = row.refs.flatMap((ref, at) => {
      const name = names[at] ?? ''

      if (!ref.startsWith('tag: ') && isCopy(name)) {
        return []
      }

      const remotes = ref.startsWith('tag: ')
        ? []
        : names
            .filter(other => isCopy(other) && other.slice(other.indexOf('/') + 1) === name)
            .map(other => ` | ${other.slice(0, other.indexOf('/'))}`)

      return [{ ref, name, tail: remotes.join('') }]
    })

    for (const { ref, name, tail } of merged) {
      const label = `${cut(name, BADGE_NAME)}${tail}`

      if (label.length + 6 > badgeRoom) {
        break
      }

      badgeRoom -= label.length + 6
      worn.push({ ref, name: label })
    }

    const unworn = merged.length - worn.length
    // The other worktrees that have this commit checked out, by folder name.
    const housed = model.worktrees
      .filter(one => !one.isCurrent && one.head !== '' && one.head.startsWith(row.hash))
      .map(one => ({ path: one.path, name: cut(one.path.split('/').pop() ?? one.path, BADGE_NAME) }))
    const badges =
      worn.reduce((sum, one) => sum + one.name.length + 6, 0) +
      (unworn > 0 ? String(unworn).length + 4 : 0) +
      housed.reduce((sum, one) => sum + one.name.length + 5, 0)
    const isCrowded =
      unworn > 0 || worn.some((one, at) => one.name !== `${merged[at]?.name}${merged[at]?.tail}`)
    const subject = row.subject === '' ? '(no message)' : row.subject

    // The title is the row's handle: pressing it opens what the commit holds.
    add(row.cells, () => [
      // A branch or tag is a badge in two parts: its icon on the lane's
      // colour, then its name on a neutral ground.
      ...worn.map(({ ref, name }) => (
        <Box flexShrink={0} marginRight={1}>
          <Text backgroundColor={laneColor(row.lane)} color="#000000">
            {' '}
            {ref.startsWith('tag: ') ? TAG_ICON : BRANCH_ICON}{' '}
          </Text>
          <Text backgroundColor={BADGE_GROUND} color="#e6e6e6" bold={ref.startsWith('HEAD')}>
            {' '}
            {name}{' '}
          </Text>
        </Box>
      )),
      unworn > 0 && (
        <Box flexShrink={0} marginRight={1}>
          <Text backgroundColor={BADGE_GROUND} color="#e6e6e6">
            {' '}
            +{unworn}{' '}
          </Text>
        </Box>
      ),
      // A worktree is a badge too, and a handle: pressed, the review moves
      // to that worktree, where it was left.
      ...housed.map(one => (
        <Box flexShrink={0} marginRight={1}>
          <Text backgroundColor={WORKTREE_COLOR} color="#000000">
            {' '}
            {WORKTREE_ICON}{' '}
          </Text>
          <Text> </Text>
          <Button
            plain
            key={`worktree:${one.path}`}
            label={one.name}
            onPress={() => actions.switchWorktree(one.path)}
          />
        </Box>
      )),
      <Box flexGrow={1} flexShrink={1} height={1} overflow="hidden">
        <Button
          plain
          key={`commit:${row.hash}`}
          // An opened commit shows its whole subject just under the row,
          // so the row itself draws a rule there, still the handle to
          // press to close it.
          label={
            selected === row.hash
              ? '─'.repeat(Math.max(8, textRoom - badges - trail.length - 1))
              : cut(subject, Math.max(8, textRoom - badges - trail.length - 1))
          }
          onPress={() => actions.open(row.hash)}
        />
      </Box>,
      <Box flexShrink={0} marginLeft={1}>
        <Text dimColor>{trail}</Text>
      </Box>,
    ])

    // The commit checked out is what everything is compared from, so it
    // offers neither a comparison nor a checkout of itself.
    details(row.hash, below, [
      // Every branch and tag on the commit, where the row had to cut them.
      ...(isCrowded
        ? wrapText(names.join(', '), textRoom - 2).map(text => () => (
            <Text color={laneColor(row.lane)}>
              {BRANCH_ICON} {text}
            </Text>
          ))
        : []),
      ...(row.hash === headHash ? [() => <Text dimColor>You are here.</Text>] : []),
      // The commit checked out can be taken back, its changes kept: asked
      // first, and then told whether it has been pushed, before it is done.
      ...(row.hash === headHash && !model.hasTarget && !model.isUndoing
        ? [
            () => (
              <Button
                key="undo"
                label="undo this commit (keep its changes)"
                onPress={actions.askUndo}
              />
            ),
          ]
        : []),
      ...(row.hash === headHash && model.isUndoing
        ? [
            () => (
              <Text color="red" bold>
                Undo this commit? {model.undoNote}
              </Text>
            ),
            () => [
              <Button key="undo-yes" label="yes, undo it" onPress={actions.undo} />,
              <Text>  </Text>,
              <Button key="undo-no" variant="primary" label="keep it" onPress={actions.keepCommit} />,
            ],
          ]
        : []),
      ...(row.hash === base ? [() => <Text dimColor>Comparing against this.</Text>] : []),
      ...(row.hash !== headHash && row.hash !== base
        ? [
            () => (
              <Button
                key={`compare:${row.hash}`}
                label={`compare ${shell.headName} with this`}
                onPress={() => actions.compareWith(row.hash)}
              />
            ),
          ]
        : []),
      ...names
        .filter(name => branches.includes(name) && name !== head)
        .map(branch => () => (
          <Button
            key={`switch:${branch}`}
            label={`check out ${branch}`}
            onPress={() => actions.checkOutBranch(branch)}
          />
        )),
      ...(row.hash !== headHash
        ? [
            () => (
              <Button
                key={`detach:${row.hash}`}
                label={`check out ${row.hash} (detached)`}
                onPress={() => actions.checkOutCommit(row.hash)}
              />
            ),
          ]
        : []),
    ])

    // The stashes made on this commit, hung under it.
    for (const one of stashes) {
      if (one.base === row.hash) {
        stashLines(one, below, false)
      }
    }

    if (below.some(cell => cell[0] !== '')) {
      add(below, () => undefined)
    }
  }

  if (graphRows.length === 0) {
    add([], () => <Text dimColor>No commits to show yet.</Text>)
  } else if (graphRows.length < GRAPH_COMMITS) {
    add([], () => <Text dimColor>The first commit: history starts here.</Text>)
  } else {
    add([], () => (
      <Text dimColor>Only the newest {GRAPH_COMMITS} commits are read.</Text>
    ))
  }

  // A stash made on a commit the graph does not reach has no row to hang
  // under, so it comes after the history.
  for (const one of stashes) {
    if (!inGraph.has(one.base ?? '')) {
      stashLines(one, [], true)
    }
  }

  // The compare panel: two fields, each taking a branch name or a commit
  // hash as typed, and under them what the field being typed in could
  // mean, to press in place of typing the rest.
  const asked = (pickField === 'a' ? pickA : pickB).toLowerCase()
  const offers = isPicking
    ? [
        ...(pickField === 'a' ? [{ value: '', label: 'working tree (your files as they are)' }] : []),
        // Another worktree, as its files stand (its uncommitted work too), and
        // the open requests: each is a comparison by itself, so either field
        // takes one.
        ...model.worktrees
          .filter(one => !one.isCurrent)
          .map(one => {
            const name = one.path.split('/').pop() ?? one.path

            return { value: `@${name}`, label: `@${name}  that worktree's files as they stand` }
          }),
        ...model.requests.map(one => ({ value: one.typed, label: `${one.typed}  ${one.title}` })),
        ...branches.map(name => ({ value: name, label: name })),
        ...graphRows
          .filter(row => row.hash !== UNCOMMITTED)
          .map(row => ({ value: row.hash, label: `${row.hash}  ${row.subject}` })),
      ]
        .filter(offer => asked === '' || offer.label.toLowerCase().includes(asked))
        .slice(0, PICK_OFFERS)
    : []
  const panel = isPicking && Input !== undefined && (
    <Box
      flexDirection="column"
      height={PICK_ROWS}
      overflow="hidden"
      borderStyle="round"
      borderColor={COMMIT_BOX}
      paddingX={1}
    >
      <Input
        key="pick-a"
        label="compare"
        placeholder="working tree, a branch, a commit, a request (#12) or @worktree"
        value={pickA}
        submitLabel="compare"
        onInput={value => actions.typeCompare('a', value)}
        onSubmit={value => actions.compare(value, pickB)}
      />
      <Input
        key="pick-b"
        label="with   "
        placeholder="a branch, a commit, a request (#12, !34, a link) or @worktree"
        value={pickB}
        submitLabel="compare"
        onInput={value => actions.typeCompare('b', value)}
        onSubmit={value => actions.compare(pickA, value)}
      />
      <Text dimColor>
        {offers.length === 0
          ? 'Nothing here matches; a full hash or ref still works.'
          : `For "${pickField === 'a' ? 'compare' : 'with'}":`}
      </Text>
      {offers.map(offer => (
        <Box height={1} overflow="hidden">
          <Button
            plain
            key={`offer:${offer.value}`}
            label={cut(offer.label, columns - 8)}
            onPress={() => actions.takeOffer(offer.value)}
          />
        </Box>
      ))}
      <Box flexGrow={1} />
      <Box columnGap={2}>
        <Button
          key="pick-go"
          variant="primary"
          label="compare"
          onPress={() => actions.compare(pickA, pickB)}
        />
        <Button key="pick-cancel" label="cancel" onPress={actions.cancelCompare} />
      </Box>
    </Box>
  )

  const HEADER_ROWS = 3 + (panel ? PICK_ROWS : 0)
  const room = clamp(shell.rows - HEADER_ROWS, 5, 400)
  // The window stops once the last line reaches its bottom row.
  const maxTop = Math.max(0, lines.length - room)
  const top = clamp(model.top, 0, maxTop)
  const shown = lines.slice(top, top + room)
  const moveTo = (line: number) => actions.scrollTo(clamp(line, 0, maxTop))

  return {
    // What the scroll hook needs to tell a tick over a body from one over
    // the graph: the kind of line on each row of the window just drawn.
    window: {
      // The comparison border's top edge is a row above the header too.
      header: HEADER_ROWS + shell.inset / 2,
      kinds: shown.map(line => line.kind),
      maxTop,
      bodyMax: Math.max(0, detailBody.length - BODY_ROWS),
    },
    tree: (
      <Box flexDirection="column">
        {statusLine(kit, shell)}
        <Box columnGap={2} height={1} overflow="hidden">
          <Button plain key="back" hotkey="b" label="back" onPress={actions.back} />
          <Button
            plain
            key="down"
            hotkey="d"
            label="down"
            onPress={() => moveTo(top + Math.floor(room / 2))}
          />
          <Button
            plain
            key="up"
            hotkey="u"
            label="up"
            onPress={() => moveTo(top - Math.floor(room / 2))}
          />
          <Button plain key="top" hotkey="g" label="top" onPress={() => moveTo(0)} />
          {helpButton(kit, actions.help)}
          <Button
            plain
            key="pick"
            hotkey="c"
            label={isPicking ? 'close compare' : 'compare…'}
            onPress={actions.toggleCompare}
          />
          <Button plain key="refresh" hotkey="r" label="refresh" onPress={actions.refresh} />
        </Box>
        <Text dimColor wrap="truncate-end">
          {Math.max(0, graphRows.length - 1)} commits · press a title or a stash's name to open
          it
        </Text>
        {panel}
        <Box flexDirection="column" height={room} overflow="hidden">
          {shown.map(line => line.draw())}
        </Box>
      </Box>
    ),
  }
}

