// The recents screen: what /lens shows when it is run outside any repo and
// was given no folder. The repos reviewed lately, each a press away, with
// the comparison it was left in; the worktrees of one repo sit together
// under it.

import type { Recent } from '../../types'
import { agoOf, comparisonLabel, groupRecents } from '../recents'
import type { Kit } from './frame'

export type RecentsActions = {
  // Picks a review up where it was left.
  open: (one: Recent) => void
  // Takes a repo off the list.
  forget: (one: Recent) => void
}

export const recentsScreen = (
  { Box, Button, Text }: Kit,
  model: { recents: readonly Recent[]; now: number },
  actions: RecentsActions,
) => {
  // A path under the person's home folder reads from `~`.
  const short = (repo: string): string => repo.replace(/^\/(Users|home)\/[^/]+\//, '~/')
  const nameOf = (path: string): string => path.split('/').pop() ?? path

  if (model.recents.length === 0) {
    return (
      <Box flexDirection="column">
        <Text bold>Nothing to review here</Text>
        <Text dimColor>
          This folder is not inside a git repository, and no repo has been reviewed yet.
        </Text>
        <Text dimColor>Name one: /lens ~/Code/my-repo [base branch or commit]</Text>
      </Box>
    )
  }

  // The first nine reviews, in the order drawn, answer to their number.
  let drawn = 0
  const row = (one: Recent, label: string, indent: number) => {
    const at = drawn

    drawn += 1

    return (
      <Box key={`recent:${one.repo}`} columnGap={1} height={1} overflow="hidden">
        <Text dimColor>
          {' '.repeat(indent)}
          {at < 9 ? String(at + 1) : ' '}
        </Text>
        <Button
          plain
          key={`open:${one.repo}`}
          {...(at < 9 ? { hotkey: String(at + 1) } : {})}
          label={label}
          onPress={() => actions.open(one)}
        />
        <Text color="#ffab40" wrap="truncate-end">
          {comparisonLabel(one)}
        </Text>
        <Text dimColor wrap="truncate-end">
          {short(one.repo)} · {agoOf(one.at, model.now)}
        </Text>
        <Box display="none" hover={{ display: 'flex' }}>
          <Button plain key={`forget:${one.repo}`} label="✕ forget" onPress={() => actions.forget(one)} />
        </Box>
      </Box>
    )
  }

  return (
    <Box flexDirection="column">
      <Text bold>Recently reviewed</Text>
      <Text dimColor wrap="truncate-end">
        This folder is not in a git repository. Pick a repo (its number), or name one: /lens
        ~/Code/my-repo
      </Text>
      <Text> </Text>
      {groupRecents(model.recents).flatMap(({ home, reviews }) =>
        // A repo reviewed in one place is one row; one with worktrees is a
        // heading and a row for each, the main checkout named as such.
        reviews.length === 1 && reviews[0]?.repo === home
          ? reviews.map(one => row(one, nameOf(one.repo), 0))
          : [
              <Text bold wrap="truncate-end">
                {nameOf(home)} <Text dimColor>{short(home)}</Text>
              </Text>,
              ...reviews.map(one =>
                row(one, one.repo === home ? 'main checkout' : `worktree ${nameOf(one.repo)}`, 2),
              ),
            ],
      )}
    </Box>
  )
}

files.hooks/screens/tree.tsx:
// The file tree: what differs, grouped by where the difference lives, with
// each file's problems counted beside it; the box that commits, stashes or
// discards the ticked files; and the stashes made earlier. It is as long as
// its lists, so the pane scrolls it.

import type { ChangedFile, Diag, LineStat, Picked } from '../../types'
import { isAwaited, isCheckable } from '../check'
import { countLabel, diagsOf } from '../diags'
import type { Stash } from '../git'
import type { Comment } from '../review'
import { clamp, wrapText } from '../text'
import type { TreeRow } from '../tree'
import { buildTree, iconOf, visibleTree } from '../tree'
import type { Kit, Shell } from './frame'
import {
  BODY_ROWS,
  COMMENT_COLOR,
  COMMENT_ICON,
  COMMIT_BOX,
  COMMIT_FILES,
  GITHUB_ICON,
  GITLAB_COLOR,
  GITLAB_ICON,
  RESOLVED_COLOR,
  STASH_COLOR,
  STASH_ICON,
  STATUS_WORD,
  helpButton,
  notesOf,
  said,
  statusLine,
} from './frame'

const OTHER_FILES = 100
// More rows than this are not drawn in one list.
const LIST_LIMIT = 300
// How many of the conversation's latest comments are listed.
const CONVERSATION_ROWS = 15
// How far an arrow moves an opened stash's body.
const BODY_STEP = 8

// What keeps the rows and folders of a request's files apart from the same
// files and folders listed above them.
const REQUEST_SPACE = 'pr:'
// The mark of a link that opens a page elsewhere.
const LINK_ICON = '\u{f08e}'

export type TreeModel = {
  shell: Shell
  // What differs, with each file's line counts; the files with uncommitted
  // edits among them; and every diagnostic the last scan found.
  files: readonly ChangedFile[]
  stats: Readonly<Record<string, LineStat>>
  dirty: readonly string[]
  diags: readonly Diag[]
  // Whether a scan has finished, so that nothing listed means nothing differs.
  isScanned: boolean
  // Whether a file is still waiting for its batch of the scan under way.
  isQueued: (path: string) => boolean
  layout: 'tree' | 'list'
  // Folders flipped from their default of open or closed; one in the tree of
  // every file is held as `all:` and its path.
  toggled: readonly string[]
  // The files ticked for a commit or a stash, and whether discarding them is
  // being confirmed.
  checked: readonly string[]
  isDiscarding: boolean
  // Whether the box of less-used keys is open.
  isMore: boolean
  // The tree of every tracked file: whether it shows, and the files.
  isBrowsing: boolean
  allFiles: readonly string[]
  isTelling: boolean
  // How many issues "send to prompt" would send.
  issuesToSend: number
  // The comments of the request under review, on files of this folder.
  comments: readonly Comment[]
  stashes: readonly Stash[]
  // The open request of the branch checked out, where it has one and no
  // comparison is on: what to call it, and what it changes.
  request:
    | {
        // Which forge it is on, what it is typed as ("#12", "!34"), its page
        // there ('' when the forge gave none) and what it is called.
        isGitlab: boolean
        typed: string
        url: string
        title: string
        files: readonly ChangedFile[]
        stats: Readonly<Record<string, LineStat>>
      }
    | undefined
  // The review box: whether it is open, and a number that changes with each
  // review sent or dropped, so its field starts empty.
  isReviewing: boolean
  reviewRound: number
  // The stash opened ('' for none), what it holds once that is read, and the
  // first line of its body in view.
  selected: string
  picked: Picked
  bodyTop: number
}

export type TreeActions = {
  refresh: () => void
  // While a request is under review: lists its threads, opens or closes the
  // box a review is submitted from, and submits one. Only the box's buttons
  // (or Enter in its field, as a comment) send anything to the forge.
  listThreads: () => void
  // Opens a file of the branch's request on what the request changes in it.
  openRequestFile: (path: string) => void
  toggleReviewing: () => void
  typeReview: (text: string) => void
  submitReview: (verdict: 'approve' | 'request-changes' | 'comment', entered?: string) => void
  // Checks every file of every project, changed or not.
  checkProject: () => void
  switchLayout: () => void
  openGraph: () => void
  stopComparing: () => void
  toggleMore: () => void
  help: () => void
  // Shows or hides the tree of every tracked file.
  toggleAllFiles: () => void
  sendIssues: () => void
  toggleTelling: () => void
  // Lists the project's names that match what was typed.
  searchNames: (query: string) => void
  open: (path: string) => void
  // Opens or closes a folder, by the key it is held under in `toggled`.
  toggleFolder: (key: string) => void
  // Ticks the paths, or unticks them when all are ticked already.
  tick: (paths: readonly string[]) => void
  // Ticks these and nothing else.
  tickOnly: (paths: readonly string[]) => void
  typeMessage: (text: string) => void
  typeDetails: (text: string) => void
  // Commits the files with the message and details typed so far; Enter in a
  // field passes that field's text as `entered`. With no files, says so.
  commit: (paths: readonly string[], entered?: { message?: string; details?: string }) => void
  stash: (paths: readonly string[]) => void
  // Discarding: asked for, confirmed, or called off.
  askDiscard: (paths: readonly string[]) => void
  discard: (paths: readonly string[]) => void
  keepChanges: () => void
  // Opens a stash under its row, or closes the one that is open.
  openStash: (ref: string) => void
  openStashFile: (ref: string, path: string) => void
  // Moves an opened stash's body so `line` is its first.
  scrollBody: (line: number) => void
  applyStash: (ref: string) => void
  popStash: (ref: string) => void
}

export const treeScreen = (kit: Kit, model: TreeModel, actions: TreeActions) => {
  const { Box, Button, Text, Input, Link } = kit
  const { shell, files, stats, diags, layout, toggled, comments, stashes, isBrowsing } = model
  const { picked: chosen } = model
  const { totals } = shell
  const statusOf = new Map(files.map(one => [one.path, one.status]))
  const changedPaths = new Set(files.map(one => one.path))
  const others = [...new Set(diags.map(diag => diag.path))]
    .filter(path => !changedPaths.has(path))
    .sort()

  // The working tree against the base in one row: lines added and deleted
  // across the changed files, and the errors and warnings found in them.
  const summary = (
    <Box>
      <Text bold>{shell.isComparing ? `Against ${shell.against} ` : 'Uncommitted '}</Text>
      <Text color="green">+{totals.added} </Text>
      <Text color="red">−{totals.deleted} </Text>
      <Text dimColor>in {totals.files} files · </Text>
      <Text color="red">{totals.errors}✖ </Text>
      <Text color="yellow">{totals.others}⚠</Text>
      {totals.fresh !== undefined && <Text bold> {totals.fresh} new</Text>}
    </Box>
  )

  // The files ticked for a commit or a stash. A tick box ticks or unticks
  // all its paths together: one file's, or every file under a folder.
  const checked = new Set(model.checked)
  const tick = (key: string, paths: readonly string[]) => (
    <Button
      plain
      key={key}
      label={
        paths.every(path => checked.has(path))
          ? '☑'
          : paths.some(path => checked.has(path))
            ? '◪'
            : '☐'
      }
      onPress={() => actions.tick(paths)}
    />
  )

  // `scope` tells apart the rows of a file that is listed twice: among the
  // changed files, and again in the tree of every file (`all:`).
  const fileRow = (
    path: string,
    mark: string,
    name = path,
    depth = 0,
    isPickable = false,
    scope = '',
  ) => {
    const counts = countLabel(diagsOf(diags, path))
    // A request's file is counted by what the request changes in it.
    const counted = scope === REQUEST_SPACE ? (model.request?.stats ?? {}) : stats
    const threads = comments.filter(one => one.path === path && one.replyTo === undefined)
    const settled = threads.filter(one => one.isResolved === true).length
    const open = threads.length - settled
    const isChecked = isCheckable(path)
    const icon = iconOf(path)
    // What happened to the file, in a word and git's usual colour for it.
    const change = STATUS_WORD[mark]
    const lead = [
      <Text>{'  '.repeat(depth)}</Text>,
      isPickable && tick(`check:${path}`, [path]),
      isPickable && <Text> </Text>,
    ]

    if (mark === 'D') {
      return (
        <Box>
          {lead}
          <Text dimColor>
            {icon.glyph} {name}
          </Text>
          <Text color="#f14c4c">  deleted</Text>
        </Box>
      )
    }

    return (
      <Box>
        {lead}
        <Text color={icon.color}>{icon.glyph} </Text>
        <Button
          plain
          key={`file:${scope}${path}`}
          // A file still being checked shows the busy mark beside what
          // has been found in it so far; its tick waits for the last tool.
          label={`${name}  ${[counts, !shell.isScanning ? '' : model.isQueued(path) ? '⋯ queued' : isAwaited(path, shell.pending) ? shell.busyMark : ''].filter(part => part !== '').join(' ') || (isChecked ? '✓' : '·')}`}
          onPress={() => (scope === REQUEST_SPACE ? actions.openRequestFile(path) : actions.open(path))}
        />
        {change !== undefined && <Text color={change[1]}>  {change[0]}</Text>}
        {/* The file's review threads (a thread is its first comment): those
            still open in the comments' colour, those resolved in gold. */}
        {open > 0 && (
          <Text color={COMMENT_COLOR}>
            {'  '}
            {COMMENT_ICON} {open}
          </Text>
        )}
        {settled > 0 && <Text color={RESOLVED_COLOR}>  ✓ {settled}</Text>}
        {counted[path] !== undefined && (
          <Text color="green">  +{counted[path]?.[0] ?? 0}</Text>
        )}
        {counted[path] !== undefined && <Text color="red"> −{counted[path]?.[1] ?? 0}</Text>}
      </Box>
    )
  }

  // `group` keeps a folder's key apart when it shows in two groups; `under`
  // is the files a tick on the folder takes, none where files are not ticked.
  // `space` keeps apart the open-or-closed state of the same folder in
  // the tree of every file, where folders start closed.
  const folderRow = (
    row: TreeRow,
    isClosed: boolean,
    group: number,
    under: readonly string[],
    space = '',
  ) => {
    const held = `${space}${row.path}`
    const counts = countLabel(diags.filter(diag => diag.path.startsWith(`${row.path}/`)))

    return (
      <Box>
        <Text dimColor>{'  '.repeat(row.depth)}</Text>
        {under.length > 0 && tick(`checkdir:${group}:${row.path}`, under)}
        {under.length > 0 && <Text> </Text>}
        <Text color="#dcb67a">{isClosed ? '\u{f07b}' : '\u{f07c}'} </Text>
        <Button
          plain
          dimColor
          key={`dir:${group}:${row.path}`}
          label={`${row.name}/${isClosed ? `  ${row.size} files` : ''}${counts === '' ? '' : `  ${counts}`}`}
          onPress={() => actions.toggleFolder(held)}
        />
      </Box>
    )
  }

  // The files are grouped by where their difference lives. Against a base
  // that is another commit there are three kinds: what the commits since
  // changed, what is edited but not committed, and what git does not
  // track at all. With no comparison only the last two exist. Only what
  // is not committed yet can be ticked for a commit or a stash.
  const dirty = new Set(model.dirty)
  const tracked = files.filter(one => one.status !== '?')
  const groups = (
    shell.isComparing
      ? [
          {
            title: shell.request === '' ? `Commits: ${shell.side} vs ${shell.against}` : shell.request,
            files: tracked.filter(one => !dirty.has(one.path)),
            isPickable: false,
          },
          {
            title: 'Uncommitted: edited since your last commit',
            files: tracked.filter(one => dirty.has(one.path)),
            isPickable: true,
          },
        ]
      : [
          {
            title: 'Uncommitted: edited since your last commit',
            files: tracked,
            isPickable: true,
          },
        ]
  )
    .concat({
      title: 'Untracked',
      files: files.filter(one => one.status === '?'),
      isPickable: true,
    })
    .filter(group => group.files.length > 0)

  const rowsFor = (group: (typeof groups)[number], at: number) =>
    layout === 'tree'
      ? visibleTree(buildTree(group.files.map(one => one.path)), toggled).map(
          ({ row, isClosed }) =>
            row.kind === 'dir'
              ? folderRow(
                  row,
                  isClosed,
                  at,
                  group.isPickable
                    ? group.files
                        .map(one => one.path)
                        .filter(path => path.startsWith(`${row.path}/`))
                    : [],
                )
              : fileRow(
                  row.path,
                  statusOf.get(row.path) ?? ' ',
                  row.name,
                  row.depth,
                  group.isPickable,
                ),
        )
      : group.files.map(one => fileRow(one.path, one.status, one.path, 0, group.isPickable))

  // The request's own files, in the layout the rest are in. Its folders keep
  // their open-or-closed state apart from the same folders above.
  const asked = model.request
  const requested = asked?.files ?? []
  // Whether the conversation is drawn as part of the request's section.
  const isInSection = asked !== undefined && requested.length > 0
  const requestStatus = new Map(requested.map(one => [one.path, one.status]))
  const requestRows =
    layout === 'tree'
      ? visibleTree(
          buildTree(requested.map(one => one.path)),
          toggled
            .filter(path => path.startsWith(REQUEST_SPACE))
            .map(path => path.slice(REQUEST_SPACE.length)),
        ).map(({ row, isClosed }) =>
          row.kind === 'dir'
            ? folderRow(row, isClosed, 98, [], REQUEST_SPACE)
            : fileRow(row.path, requestStatus.get(row.path) ?? ' ', row.name, row.depth, false, REQUEST_SPACE),
        )
      : requested.map(one => fileRow(one.path, one.status, one.path, 0, false, REQUEST_SPACE))

  // What a commit or a stash would take: the ticked files still listed.
  const pickable = groups
    .filter(group => group.isPickable)
    .flatMap(group => group.files.map(one => one.path))
  const ticked = pickable.filter(path => checked.has(path))
  const isAllTicked = pickable.length > 0 && ticked.length === pickable.length
  // The commit box is there whenever something could be committed, ticked
  // or not, and is always the same height: ticking a file changes what it
  // says, never where the lists under it sit. The discard question takes
  // the buttons' own row for the same reason.
  const isDiscarding = model.isDiscarding && ticked.length > 0
  const gitBar = pickable.length > 0 && (
    <Box
      flexDirection="column"
      borderStyle="round"
      borderColor={COMMIT_BOX}
      borderDimColor={ticked.length === 0}
      paddingX={1}
      marginY={1}
    >
      <Box columnGap={2} height={1} overflow="hidden">
        <Button
          plain
          key="tick-all"
          hotkey="s"
          label={isAllTicked ? 'select none' : 'select all'}
          onPress={() => actions.tickOnly(isAllTicked ? [] : pickable)}
        />
        {ticked.length === 0 ? (
          <Text dimColor>Tick files (☐) below to commit, stash or discard them.</Text>
        ) : (
          <Text bold color={COMMIT_BOX}>
            {ticked.length} {ticked.length === 1 ? 'file' : 'files'} selected
          </Text>
        )}
      </Box>
      {/* Each field has a row to itself, so a long message has the box's
          whole width. A field is one line, so a longer message goes in the
          second, which becomes the commit's body. */}
      {Input !== undefined && (
        <Input
          key="message"
          label="message"
          placeholder="what changed"
          submitLabel="commit"
          onInput={actions.typeMessage}
          onSubmit={value => actions.commit(ticked, { message: value })}
        />
      )}
      {Input !== undefined && (
        <Input
          key="body"
          label="details"
          placeholder="optional: why, and anything worth knowing"
          submitLabel="commit"
          onInput={actions.typeDetails}
          onSubmit={value => actions.commit(ticked, { details: value })}
        />
      )}
      {isDiscarding ? (
        // Discarding cannot be undone, so it takes a second press that
        // says what will be lost.
        <Box columnGap={2} marginTop={1} height={1} overflow="hidden">
          <Text color="red" bold>
            Throw away the changes in {ticked.length}{' '}
            {ticked.length === 1 ? 'file' : 'files'}? It cannot be undone.
          </Text>
          <Button key="discard-yes" label="yes, discard" onPress={() => actions.discard(ticked)} />
          <Button
            key="discard-no"
            variant="primary"
            label="keep them"
            onPress={actions.keepChanges}
          />
        </Box>
      ) : (
        <Box columnGap={2} marginTop={1} height={1} overflow="hidden">
          <Button
            key="commit"
            variant={ticked.length === 0 ? 'secondary' : 'primary'}
            dimColor={ticked.length === 0}
            label={`\u{f417} commit ${ticked.length}`}
            onPress={() => actions.commit(ticked)}
          />
          <Button
            key="stash"
            dimColor={ticked.length === 0}
            label={`\u{f187} stash ${ticked.length}`}
            onPress={() => actions.stash(ticked)}
          />
          <Button
            key="discard"
            dimColor={ticked.length === 0}
            label={`\u{f1f8} discard ${ticked.length}`}
            onPress={() => actions.askDiscard(ticked)}
          />
        </Box>
      )}
    </Box>
  )

  // Every file git tracks, for reading one the change does not touch.
  // Folders start closed here, and keep their own open-or-closed state.
  const everything = model.allFiles
  const everyRow = visibleTree(
    buildTree(everything),
    toggled.filter(path => path.startsWith('all:')).map(path => path.slice(4)),
    true,
  ).map(({ row, isClosed }) =>
    row.kind === 'dir'
      ? folderRow(row, isClosed, 99, [], 'all:')
      : fileRow(row.path, statusOf.get(row.path) ?? ' ', row.name, row.depth, false, 'all:'),
  )

  // The picked stash's message is wrapped here, to the width its box has,
  // so the box can show a fixed number of its lines.
  const messageWidth = clamp(shell.columns - 16, 24, 100)
  const bodyLines = wrapText(chosen.body, messageWidth - 4)
  const bodyTop = clamp(model.bodyTop, 0, bodyLines.length - BODY_ROWS)
  // The files of the picked stash; pressing one opens it as the stash left
  // it, in the diff view.
  const filesOf = (id: string, indent: number) =>
    model.selected === id &&
    chosen.hash === id && (
      <Box flexDirection="column" marginLeft={indent}>
        {/* The subject in full: the graph's row cuts it short in a narrow pane. */}
        {chosen.subject !== '' && (
          <Box width={messageWidth}>
            <Text bold>{chosen.subject}</Text>
          </Box>
        )}
        {/* The body in a box of a fixed height, so a long one cannot push
            the lists away; the arrows move its window a few lines at a time. */}
        {bodyLines.length > 0 && (
          <Box
            flexDirection="column"
            width={messageWidth}
            borderStyle="round"
            borderDimColor
            paddingX={1}
          >
            {bodyLines.slice(bodyTop, bodyTop + BODY_ROWS).map(line => (
              <Text italic dimColor>
                {line === '' ? ' ' : line}
              </Text>
            ))}
            {bodyLines.length > BODY_ROWS && (
              <Box columnGap={2}>
                <Button
                  plain
                  key={`body-up:${id}`}
                  label="▲"
                  onPress={() => actions.scrollBody(Math.max(0, bodyTop - BODY_STEP))}
                />
                <Button
                  plain
                  key={`body-down:${id}`}
                  label="▼"
                  onPress={() =>
                    actions.scrollBody(Math.min(bodyLines.length - BODY_ROWS, bodyTop + BODY_STEP))
                  }
                />
                <Text dimColor>
                  lines {bodyTop + 1}–{Math.min(bodyLines.length, bodyTop + BODY_ROWS)} of{' '}
                  {bodyLines.length}
                </Text>
              </Box>
            )}
          </Box>
        )}
        {chosen.files.length === 0 && <Text dimColor>No files changed here.</Text>}
        {chosen.files.slice(0, COMMIT_FILES).map(one => {
          const icon = iconOf(one.path)
          const stat = chosen.stats[one.path]
          const change = STATUS_WORD[one.status]

          return (
            <Box>
              <Text color={icon.color}>{icon.glyph} </Text>
              <Button
                plain
                key={`changed:${id}:${one.path}`}
                label={one.path}
                onPress={() => actions.openStashFile(id, one.path)}
              />
              {change !== undefined && <Text color={change[1]}>  {change[0]}</Text>}
              {stat !== undefined && <Text color="green">  +{stat[0]}</Text>}
              {stat !== undefined && <Text color="red"> −{stat[1]}</Text>}
            </Box>
          )
        })}
        {chosen.files.length > COMMIT_FILES && (
          <Text dimColor>… {chosen.files.length - COMMIT_FILES} more files</Text>
        )}
      </Box>
    )
  // A stash's row, and under it what the stash holds when it is opened.
  const stashRow = (one: Stash) => [
    <Box>
      <Text backgroundColor={STASH_COLOR} color="#000000">
        {' '}
        {STASH_ICON}{' '}
      </Text>
      <Text> </Text>
      <Button plain key={`stash:${one.ref}`} label={one.ref} onPress={() => actions.openStash(one.ref)} />
      <Box flexGrow={1} flexShrink={1}>
        <Text dimColor wrap="truncate-end">
          {' '}
          {one.subject}
        </Text>
      </Box>
      <Box flexShrink={0} columnGap={1} marginLeft={1}>
        <Text dimColor>
          {one.base ? `on ${one.base} · ` : ''}
          {(one.when ?? '').replace(' ago', '')}
        </Text>
        <Button
          plain
          key={`apply:${one.ref}`}
          label="apply"
          onPress={() => actions.applyStash(one.ref)}
        />
        <Button plain key={`pop:${one.ref}`} label="pop" onPress={() => actions.popStash(one.ref)} />
      </Box>
    </Box>,
    filesOf(one.ref, 2),
  ]

  return (
    <Box flexDirection="column">
      {statusLine(kit, shell)}
      <Box gap={2}>
        <Button plain key="refresh" hotkey="r" label="refresh" onPress={actions.refresh} />
        <Button
          plain
          key="layout"
          hotkey="t"
          label={layout === 'tree' ? 'list view' : 'tree view'}
          onPress={actions.switchLayout}
        />
        <Button plain key="graph" hotkey="g" label="git graph" onPress={actions.openGraph} />
        {shell.reviewing !== '' && (
          <Button
            plain
            key="threads"
            hotkey="c"
            label={`threads (${comments.filter(one => one.replyTo === undefined && one.path !== '').length})`}
            onPress={actions.listThreads}
          />
        )}
        {shell.reviewing !== '' && (
          <Button
            plain
            key="review"
            hotkey="v"
            label={model.isReviewing ? 'close review' : 'submit review'}
            onPress={actions.toggleReviewing}
          />
        )}
        {shell.isComparing && (
          <Button
            plain
            key="uncompare"
            hotkey="x"
            label="stop comparing"
            onPress={actions.stopComparing}
          />
        )}
        <Button
          plain
          key="more"
          hotkey="m"
          label={model.isMore ? 'less' : 'more…'}
          onPress={actions.toggleMore}
        />
        {helpButton(kit, actions.help)}
      </Box>
      {/* The less-used keys open in a box of their own (m): a key works
          while its button is drawn, so the box is where these live. */}
      {model.isMore && (
        <Box flexDirection="column" borderStyle="round" borderDimColor paddingX={1}>
          <Box columnGap={2} flexWrap="wrap">
            <Button
              plain
              key="project"
              hotkey="a"
              label="check whole project"
              onPress={actions.checkProject}
            />
            <Button
              plain
              key="browse"
              hotkey="w"
              label={isBrowsing ? 'changed files only' : 'all files'}
              onPress={actions.toggleAllFiles}
            />
            <Button
              plain
              key="send-issues"
              hotkey="n"
              label={`send ${model.issuesToSend} ${model.issuesToSend === 1 ? 'issue' : 'issues'} to prompt`}
              onPress={actions.sendIssues}
            />
            <Button
              plain
              key="tell"
              hotkey="i"
              label={`tell Claude about new errors: ${model.isTelling ? 'on' : 'off'}`}
              onPress={actions.toggleTelling}
            />
          </Box>
          {/* A name anywhere in the project, by typing part of it: the
              language server of the first changed file it can read searches. */}
          {Input !== undefined && (
            <Box height={1} overflow="hidden">
              <Input
                key="symbol-search"
                label="go to name"
                placeholder="part of a function, class or type name, then Enter"
                submitLabel="search"
                onSubmit={actions.searchNames}
              />
            </Box>
          )}
        </Box>
      )}
      {notesOf(kit, shell.notes)}
      {/* The review box: a summary, then what the review says of the
          request. Nothing is sent until one of its buttons is pressed. */}
      {model.isReviewing && Input !== undefined && shell.reviewing !== '' && (
        <Box flexDirection="column" borderStyle="round" borderColor={COMMIT_BOX} paddingX={1}>
          <Input
            key={`review-text:${model.reviewRound}`}
            label="review"
            placeholder="a summary of your review (needed to comment or request changes)"
            submitLabel="comment"
            autoFocus
            onInput={actions.typeReview}
            onSubmit={value => actions.submitReview('comment', value)}
          />
          <Box columnGap={2}>
            <Button key="review-approve" variant="primary" label="✓ approve" onPress={() => actions.submitReview('approve')} />
            <Button key="review-changes" label="✎ request changes" onPress={() => actions.submitReview('request-changes')} />
            <Button key="review-comment" label="comment only" onPress={() => actions.submitReview('comment')} />
            <Button key="review-cancel" label="cancel" onPress={actions.toggleReviewing} />
          </Box>
        </Box>
      )}
      {summary}
      {gitBar}
      {files.length === 0 && model.isScanned && (
        <Text dimColor>
          {shell.isComparing ? `Nothing differs from ${shell.against}.` : 'Nothing is modified.'}
        </Text>
      )}
      {groups.flatMap((group, at) => {
        const rows = rowsFor(group, at)

        return [
          <Text bold>
            {group.title} ({group.files.length})
          </Text>,
          ...rows.slice(0, LIST_LIMIT),
          rows.length > LIST_LIMIT && (
            <Text dimColor>… {rows.length - LIST_LIMIT} more rows not shown</Text>
          ),
        ]
      })}
      {/* The request of the branch checked out: every file it changes, with
          the threads on each, whether or not the file is edited here. */}
      {/* A clear row sets the request apart from the working tree's files. */}
      {asked !== undefined && requestRows.length > 0 && <Text> </Text>}
      {asked !== undefined && requestRows.length > 0 && (
        // The forge's mark, then the request: its number is a link to its
        // page there, where the surface draws links.
        <Text bold wrap="truncate-end">
          <Text color={asked.isGitlab ? GITLAB_COLOR : undefined}>
            {asked.isGitlab ? GITLAB_ICON : GITHUB_ICON}
          </Text>{' '}
          {asked.isGitlab ? 'MR' : 'PR'}{' '}
          {Link !== undefined && asked.url.startsWith('https://') ? (
            // In a link's colour, underlined, with the mark of a page that
            // opens elsewhere: a number alone does not look pressable.
            <Text color={COMMIT_BOX} underline>
              <Link href={asked.url}>
                {asked.typed} {LINK_ICON}
              </Link>
            </Text>
          ) : (
            asked.typed
          )}
          {asked.title === '' ? '' : `: ${asked.title}`} ({asked.files.length})
        </Text>
      )}
      {requestRows.slice(0, LIST_LIMIT)}
      {/* What was said on the request as a whole, and the comments that
          no longer sit on a line (the code under them has changed). Under
          the request's own heading it is part of that section. */}
      {comments.some(one => one.line === 0) && (
        <Text bold={!isInSection} dimColor={isInSection}>
          {isInSection ? '  ' : ''}Conversation ({comments.filter(one => one.line === 0).length})
        </Text>
      )}
      {comments
        .filter(one => one.line === 0)
        .slice(-CONVERSATION_ROWS)
        .map(one => (
          <Text color={one.path === '' ? undefined : COMMENT_COLOR} wrap="truncate-end">
            {isInSection ? '  ' : ''}
            {COMMENT_ICON} {one.path === '' ? '' : `${one.path} (outdated) · `}
            {said(one)}
          </Text>
        ))}
      {others.length > 0 && <Text bold>Other files with issues ({others.length})</Text>}
      {others.slice(0, OTHER_FILES).map(path => fileRow(path, ' '))}
      {isBrowsing && <Text bold>All files ({everything.length})</Text>}
      {isBrowsing && everything.length === 0 && <Text dimColor>Reading the file list…</Text>}
      {everyRow.slice(0, LIST_LIMIT)}
      {everyRow.length > LIST_LIMIT && (
        <Text dimColor>… {everyRow.length - LIST_LIMIT} more rows; open a folder to narrow</Text>
      )}
      {/* What was stashed earlier: apply keeps the stash, pop removes it
          once its changes are back. */}
      {stashes.length > 0 && <Text bold>Stashes ({stashes.length})</Text>}
      {stashes.flatMap(one => stashRow(one))}
    </Box>
  )
}

files.hooks/semantic.ts:
import type { Span } from '../types'
import type { InlayHint, OutlineItem, PlaceLine, SemanticToken } from './lsp-types'

// What VS Code's Dark Modern (Dark+) theme gives each semantic token type, by
// way of the TextMate scope VS Code maps the type to. The types the tokenizer
// already colours well (keyword, comment, string, number, operator, regexp) are
// left out on purpose: it tells the two keyword colours apart and a server
// does not.
const TYPE_COLORS: Record<string, string> = {
  namespace: '#4EC9B0',
  type: '#4EC9B0',
  class: '#4EC9B0',
  struct: '#4EC9B0',
  interface: '#4EC9B0',
  enum: '#4EC9B0',
  typeParameter: '#4EC9B0',
  function: '#DCDCAA',
  method: '#DCDCAA',
  macro: '#DCDCAA',
  decorator: '#DCDCAA',
  variable: '#9CDCFE',
  parameter: '#9CDCFE',
  property: '#9CDCFE',
  event: '#9CDCFE',
  enumMember: '#4FC1FF',
  label: '#C8C8C8',
  // Pylance's own names for `self` and `cls`.
  selfParameter: '#9CDCFE',
  clsParameter: '#9CDCFE',
}

const CONSTANT_COLOR = '#4FC1FF'

// The colour VS Code's Dark Modern theme gives a semantic token, or '' to leave
// the tokenizer's colour as it is. A readonly variable or property is a
// constant; no other modifier changes a colour in this theme. Own keys only:
// a type named 'constructor' must not find something on Object.prototype.
export const semanticColor = (type: string, modifiers: readonly string[]): string =>
  (type === 'variable' || type === 'property') && modifiers.includes('readonly')
    ? CONSTANT_COLOR
    : Object.hasOwn(TYPE_COLORS, type)
      ? (TYPE_COLORS[type] ?? '')
      : ''

// How many characters of span text a character of the file's own text became:
// the highlighter draws a tab as four spaces and drops other control characters.
const widthOf = (char: string): number =>
  char === '\t' ? 4 : char < ' ' || char === '\u007f' ? 0 : 1

// Maps a 1-based column of the file's text to a 0-based index into the line's
// span text. Without the raw line, or past its end, a character is one wide.
const indexer = (rawLine: string | undefined): ((col: number) => number) => {
  const starts = [0]

  for (const char of rawLine ?? '') {
    for (let unit = 0; unit < char.length; unit += 1) {
      starts.push((starts[starts.length - 1] ?? 0) + (unit === 0 ? widthOf(char) : 1))
    }
  }

  const end = starts[starts.length - 1] ?? 0

  return col => {
    const at = Number.isFinite(col) ? Math.max(0, Math.floor(col) - 1) : 0

    return starts[at] ?? end + (at - (starts.length - 1))
  }
}

// One line's spans recoloured by the semantic tokens on that line. A span is
// split where a token starts or ends; only colours change, never text, and
// text no token covers (or whose token has no colour) keeps the tokenizer's.
export const applySemantic = (
  spans: readonly Span[],
  tokens: readonly SemanticToken[],
  rawLine?: string,
): Span[] => {
  const indexOf = indexer(rawLine)
  const ranges = tokens.flatMap(token => {
    const color = semanticColor(token.type, token.modifiers ?? [])
    const from = indexOf(token.col)
    const to = indexOf(token.col + Math.max(0, token.length))

    return color !== '' && to > from ? [{ from, to, color }] : []
  })

  if (ranges.length === 0) {
    return spans.map(([color, text]) => [color, text])
  }

  const out: Span[] = []
  let offset = 0

  for (const [color, text] of spans) {
    const cuts = new Set([0, text.length])

    for (const range of ranges) {
      for (const edge of [range.from - offset, range.to - offset]) {
        if (edge > 0 && edge < text.length) {
          cuts.add(edge)
        }
      }
    }

    const edges = [...cuts].sort((a, b) => a - b)

    if (text === '') {
      out.push([color, text])
    }

    edges.slice(0, -1).forEach((from, at) => {
      const start = offset + from
      const hit = ranges.find(range => start >= range.from && start < range.to)

      out.push([hit?.color ?? color, text.slice(from, edges[at + 1])])
    })
    offset += text.length
  }

  return out
}

// VS Code Dark Modern's editorInlayHint.foreground.
export const INLAY_COLOR = '#969696'

// A hint as it reads in the code. Servers send the label bare and say "pad
// this side" apart from it, so the padding is put back: ': int' after a name,
// ' -> int' after a signature, 'amount=' before an argument.
const hintText = (hint: InlayHint): string => {
  const label = String(hint.label ?? '').replace(/[\u0000-\u001f\u007f]/g, ' ')

  if (label.trim() === '') {
    return ''
  }

  if (hint.kind === 'type') {
    return /^[\s:]/.test(label) ? label : label.startsWith('->') ? ` ${label}` : `: ${label}`
  }

  if (hint.kind === 'parameter') {
    return /[\s=]$/.test(label) ? label : label.endsWith(':') ? `${label} ` : `${label}=`
  }

  return label
}

// One line's spans with the server's inlay hints put in where they sit, each a
// span of its own in INLAY_COLOR. `isHint` runs alongside `spans`, one flag a
// span: true for a hint, which is not text of the file.
export const applyInlays = (
  spans: readonly Span[],
  hints: readonly InlayHint[],
  rawLine?: string,
): { spans: Span[]; isHint: boolean[] } => {
  const indexOf = indexer(rawLine)
  // Sorting is stable, so hints at one column keep the server's order.
  const placed = hints
    .map(hint => ({ at: indexOf(hint.col), text: hintText(hint) }))
    .filter(hint => hint.text !== '')
    .sort((a, b) => a.at - b.at)
  const out: Span[] = []
  const isHint: boolean[] = []
  let next = 0
  let offset = 0

  const push = (color: string, text: string, hinted: boolean): void => {
    out.push([color, text])
    isHint.push(hinted)
  }

  for (const [color, text] of spans) {
    let done = 0

    for (let hint = placed[next]; hint !== undefined && hint.at < offset + text.length; hint = placed[next]) {
      const cut = Math.max(done, hint.at - offset)

      if (cut > done) {
        push(color, text.slice(done, cut), false)
      }

      push(INLAY_COLOR, hint.text, true)
      done = cut
      next += 1
    }

    if (done < text.length || text === '') {
      push(color, text.slice(done), false)
    }

    offset += text.length
  }

  // A hint at or past the end of the line goes after its last character.
  for (const hint of placed.slice(next)) {
    push(INLAY_COLOR, hint.text, true)
  }

  return { spans: out, isHint }
}

// The innermost outline item that starts on `line`, as the fold a press on
// that line means: its first and last line.
export const foldOf = (
  items: readonly OutlineItem[],
  line: number,
): { from: number; to: number } | undefined => {
  const inner = items
    .filter(item => item.line === line)
    .reduce<OutlineItem | undefined>(
      (best, item) => (best === undefined || item.depth > best.depth ? item : best),
      undefined,
    )

  return inner === undefined ? undefined : { from: line, to: Math.max(line, inner.endLine) }
}

// The chain of outline items that contain `line`, outermost first, for a
// breadcrumb. Items come parent before child, so each one deeper than the
// chain's last extends it; of two items side by side on a line the first wins.
export const enclosing = (items: readonly OutlineItem[], line: number): OutlineItem[] => {
  const chain: OutlineItem[] = []

  for (const item of items) {
    if (line >= item.line && line <= item.endLine && item.depth > (chain[chain.length - 1]?.depth ?? -1)) {
      chain.push(item)
    }
  }

  return chain
}

const KIND_MARKS: Record<string, string> = {
  function: 'ƒ',
  method: 'ƒ',
  constructor: 'ƒ',
  class: 'C',
  interface: 'I',
  enum: 'E',
  variable: 'v',
  property: 'v',
  field: 'v',
  constant: 'c',
}

// Own keys only: a kind named 'constructor' or 'toString' must not find
// something on Object.prototype.
const markOf = (kind: string): string => (Object.hasOwn(KIND_MARKS, kind) ? (KIND_MARKS[kind] ?? '·') : '·')

// The outline as rows to list: indent, a mark for the kind, the name and the
// lines it spans.
export const outlineRows = (items: readonly OutlineItem[]): { item: OutlineItem; label: string }[] =>
  items.map(item => ({
    item,
    label: `${'  '.repeat(Math.max(0, item.depth))}${markOf(item.kind)} ${item.name} ${
      item.endLine > item.line ? `${item.line}-${item.endLine}` : item.line
    }`,
  }))

// Places grouped by file for a list: the file under review first, then the
// repo's other files, then files outside it, each group by path; a file's
// places by line.
export const groupPlaces = (
  places: readonly PlaceLine[],
  current: string,
): { total: number; files: { path: string; isInRepo: boolean; places: PlaceLine[] }[] } => {
  const byPath = new Map<string, { path: string; isInRepo: boolean; places: PlaceLine[] }>()

  for (const place of places) {
    const file = byPath.get(place.path) ?? { path: place.path, isInRepo: place.isInRepo, places: [] }
    byPath.set(place.path, file)
    file.places.push(place)
  }

  const files = [...byPath.values()].sort(
    (a, b) =>
      Number(b.path === current) - Number(a.path === current) ||
      Number(b.isInRepo) - Number(a.isInRepo) ||
      (a.path < b.path ? -1 : a.path > b.path ? 1 : 0),
  )

  for (const file of files) {
    file.places.sort((a, b) => a.line - b.line || a.col - b.col)
  }

  return { total: places.length, files }
}

// Where a name is used, as the prompt takes it: a line each, in the order
// given, and a count of those past `limit`.
export const placesList = (name: string, places: readonly PlaceLine[], limit: number): string => {
  if (places.length === 0) {
    return `No uses of \`${name}\` found.`
  }

  const shown = places.slice(0, Math.max(0, limit))
  const rest = places.length - shown.length

  return [
    `\`${name}\` is used in ${places.length} ${places.length === 1 ? 'place' : 'places'}:`,
    ...shown.map(
      place => `- ${place.path}:${place.line}:${place.col} ${place.text.replace(/\s+/g, ' ').trim()}`,
    ),
    ...(rest > 0 ? [`- … and ${rest} more`] : []),
  ].join('\n')
}

files.hooks/settings.ts:
// The person's settings, as the config menu holds them (the manifest's
// `userConfig`), read into the shape the rest of the mod asks about. A value
// that is missing or of the wrong kind is its default, so nothing downstream
// has to doubt one.

import { PAD } from './kit/layout'

// Which checkers a scan may use. A language server answers in the name of
// its command-line twin (pyright for Python, tsc for TypeScript, terraform),
// so switching a checker off silences both.
export type Checkers = {
  ruff: boolean
  pyright: boolean
  tsc: boolean
  eslint: boolean
  terraform: boolean
  // Whether the language servers are asked before the command-line checkers
  // (and at all, for a language that has no command-line checker here).
  servers: boolean
}

export type Settings = {
  checkers: Checkers
  // Whether the base is checked too, to tell a new problem from an old one.
  marksNew: boolean
  // The cells left clear at each side of every screen.
  sidePadding: number
  // Whether the less-used keys always show, instead of under "more…".
  showsAllKeys: boolean
  // Whether /lens picks a repo up where it was left (its comparison and
  // layout), and whether what a session left behind is removed when it ends.
  remembers: boolean
  cleansUp: boolean
}

export const ALL_CHECKERS: Checkers = {
  ruff: true,
  pyright: true,
  tsc: true,
  eslint: true,
  terraform: true,
  servers: true,
}

export const DEFAULTS: Settings = {
  checkers: ALL_CHECKERS,
  marksNew: true,
  sidePadding: PAD,
  showsAllKeys: false,
  remembers: true,
  cleansUp: true,
}

const MOST_PADDING = 8

export const settingsOf = (options: Readonly<Record<string, unknown>>): Settings => {
  const flag = (name: string, fallback: boolean): boolean => {
    const value = options[name]

    return typeof value === 'boolean' ? value : fallback
  }
  const padding = options.sidePadding

  return {
    checkers: {
      ruff: flag('ruff', true),
      pyright: flag('pyright', true),
      tsc: flag('tsc', true),
      eslint: flag('eslint', true),
      terraform: flag('terraform', true),
      servers: flag('languageServers', true),
    },
    marksNew: flag('markNew', DEFAULTS.marksNew),
    sidePadding:
      typeof padding === 'number' && Number.isFinite(padding)
        ? Math.min(MOST_PADDING, Math.max(0, Math.round(padding)))
        : DEFAULTS.sidePadding,
    showsAllKeys: options.keys === 'all shown',
    remembers: flag('remember', DEFAULTS.remembers),
    cleansUp: flag('cleanUp', DEFAULTS.cleansUp),
  }
}

files.hooks/source.ts:
// A whole file as coloured lines, for the file screen.

import type { Span } from '../types'
import { HIGHLIGHT_PY } from './highlight'
import type { Run } from './run'
import { tail } from './run'

// Reads a whole file through the highlighter; when that cannot run the lines
// are the file's plain text, and `note` says why.
//
// `committed` is the file's text as a commit left it, which the highlighter
// then reads from stdin; without it the highlighter (or, failing that,
// `readFile`, which answers '' for a file it cannot read) reads the working
// tree's file.
export const readSource = async (
  run: Run,
  readFile: (path: string) => Promise<string>,
  repo: string,
  path: string,
  committed: string | undefined,
): Promise<{ lines: Span[][]; note: string }> => {
  const ran = await run(
    [
      'uv',
      'run',
      '--no-project',
      '--with',
      'pygments',
      'python',
      '-c',
      HIGHLIGHT_PY,
      path,
      '1',
      '10000000',
      // A last argument has the highlighter read the text from stdin.
      ...(committed === undefined ? [] : ['-']),
    ],
    { cwd: repo, timeoutMs: 30_000, ...(committed === undefined ? {} : { stdin: committed }) },
  )

  try {
    return { lines: (JSON.parse(ran.stdout) as { lines: Span[][] }).lines, note: '' }
  } catch {
    const text = committed ?? (await readFile(`${repo}/${path}`))

    return {
      lines: text
        .split('\n')
        .map((line): Span[] => [['', line.replace(/[\u0000-\u001f\u007f]/g, ' ')]]),
      note: `highlighting did not run: ${tail(ran.stderr) || 'no output'}`,
    }
  }
}

files.hooks/state.ts:
// The pane's state as the session holds it: what each value is before
// anything is known, how a value kept from an older version of the mod is
// read, and what every screen derives from it.
//
// The atoms themselves are declared in the hooks module (register.tsx): the
// engine reads a state reference only where it is written in that file.

import type {
  Crumb,
  Diag,
  GraphRow,
  Listing,
  Lookup,
  Picked,
  Scan,
  Source,
  View,
} from '../types'
import { sumStats } from './git'
import { shortRef } from './text'

export const NO_SYMBOL: Lookup = {
  file: '',
  name: '',
  at: 0,
  col: 0,
  text: '',
  path: '',
  line: 0,
  typePath: '',
  typeLine: 0,
  hasImplementations: false,
  signature: '',
}
// The breadcrumb's popover, closed.
export const NO_CRUMB: Crumb = { kind: 'none', dir: '', level: 0, left: 0, top: -1 }

export const NO_VIEW: View = {
  repo: '',
  base: 'HEAD',
  screen: 'tree',
  file: '',
  top: 1,
  cursor: -1,
  isExpanded: false,
  layout: 'tree',
  toggled: [],
  selected: '',
  isDiff: false,
  commit: '',
  checked: [],
  origin: 'graph',
  bodyTop: 0,
  graphTop: 0,
  target: '',
  baseWorktree: '',
  request: '',
  requestTyped: '',
  isCommenting: false,
  commentLine: 0,
  replyTo: '',
  diffBase: { path: '', base: '', name: '' },
  hidesResolved: false,
  isReviewing: false,
  isPreview: true,
  isFinding: false,
  find: '',
  findAt: 0,
  isDiscarding: false,
  isHelp: false,
  symbol: NO_SYMBOL,
  isHinting: false,
  listBack: 'file',
  isMore: false,
  crumb: NO_CRUMB,
  backFile: '',
  backCommit: '',
  backTop: 1,
  isUndoing: false,
  undoNote: '',
  isBlame: false,
  isBrowsing: false,
  extra: [],
  isTelling: false,
  isPicking: false,
  pickA: '',
  pickB: '',
  pickField: 'b',
}
export const NO_SCAN: Scan = {
  status: 'idle',
  files: [],
  diags: [],
  changed: {},
  notes: [],
  isProjectChecked: false,
  stats: {},
  graph: [],
  graphCount: 0,
  branches: [],
  head: '',
  headHash: '',
  dirty: [],
  stashes: [],
  worktrees: [],
  pending: [],
  faded: [],
  checked: 0,
  toCheck: 0,
}
export const NO_SOURCE: Source = { path: '', lineCount: 0, note: '', stamp: 0 }
export const NO_LISTING: Listing = { title: '', rows: [], prompt: '' }
export const NO_PICKED: Picked = { hash: '', files: [], stats: {}, subject: '', body: '' }

// A session keeps its state across a reload of the mod, so a value written
// by an older version may lack the fields added since, whatever its type
// says. Read through these, such a value has every field: a missing one is
// its default, and a reader need not ask.
export const settledView = (stored: View): View => ({ ...NO_VIEW, ...stored })
export const settledScan = (stored: Scan): Scan => ({ ...NO_SCAN, ...stored })
export const settledPicked = (stored: Picked): Picked => ({ ...NO_PICKED, ...stored })

// What is being compared with what, in the words every screen uses.
export type Comparison = {
  // What is checked out, by branch name where there is one.
  headName: string
  // The side the comparison is read from: the target, or what is checked out.
  side: string
  // What it is read against: the base, by a branch on its commit where
  // there is one.
  against: string
  // Whether anything but the uncommitted changes is compared. A base that is
  // the commit checked out compares it with itself, which is the same as no
  // comparison; with a target the comparison is between two commits of the
  // person's choosing and what is checked out plays no part.
  isComparing: boolean
  // The pull or merge request under review as a label, and what was typed to
  // open it, by which the forge is asked about it; '' when there is none.
  request: string
  requestTyped: string
}

export const comparisonOf = (now: View, found: Scan, history: readonly GraphRow[]): Comparison => {
  const headName =
    found.head === '' || found.head === 'HEAD'
      ? found.headHash || 'HEAD'
      : found.head
  // The base may be named by hash or by a branch or tag on its commit.
  const baseRow = history.find(
    row =>
      row.hash === now.base ||
      (row.refs ?? []).some(ref => ref.replace(/^(HEAD -> |tag: )/, '') === now.base),
  )
  const baseBranch = baseRow?.refs
    ?.map(ref => ref.replace(/^HEAD -> /, ''))
    .find(ref => found.branches.includes(ref))
  const request = now.target === '' ? '' : now.request

  return {
    headName,
    side: now.target === '' ? headName : shortRef(now.target),
    against:
      (now.baseWorktree ?? '') !== ''
        ? // As it is typed in the compare panel: the worktree's files as they stand.
          `@${now.baseWorktree.split('/').pop() ?? ''}`
        : (baseBranch ?? shortRef(now.base)),
    isComparing:
      now.target !== '' ||
      (now.base !== 'HEAD' &&
        now.base !== found.head &&
        now.base !== found.headHash &&
        (baseRow === undefined || baseRow.hash !== found.headHash)),
    request,
    requestTyped: request === '' ? '' : now.requestTyped,
  }
}

// The diagnostics in the files that differ: the ones a change answers for.
export const changedDiags = (found: Scan): Diag[] => {
  const changed = new Set(found.files.map(one => one.path))

  return found.diags.filter(diag => changed.has(diag.path))
}

// The changed files in one row of numbers; `inChanged` is `changedDiags`.
export const totalsOf = (found: Scan, inChanged: readonly Diag[]) => {
  const [added, deleted] = sumStats(found.files.map(one => found.stats[one.path] ?? [0, 0]))
  const errors = inChanged.filter(diag => diag.severity === 'error').length

  return {
    files: found.files.length,
    added,
    deleted,
    errors,
    others: inChanged.length - errors,
    fresh: inChanged.some(diag => diag.isNew !== undefined)
      ? inChanged.filter(diag => diag.isNew === true).length
      : undefined,
  }
}

