// A line of code as it is drawn: the highlighter's spans cut where a
// diagnostic, a search match or unused code starts and ends, with the
// language server's inlay hints set among them.

import type { Span } from '../types'
import type { InlayHint } from './lsp-types'
import { applyInlays, INLAY_COLOR } from './semantic'

// A stretch of a line as it is drawn: its colour, and whether it is under a
// diagnostic, a search match, code that is never used, or is an inlay hint
// (text the server adds, which is not in the file).
export type Part = {
  color: string
  text: string
  isMarked: boolean
  isFound: boolean
  isFaded: boolean
  isHint: boolean
}

// A line's parts with the server's inlay hints set among them. The hints are
// placed by a helper that knows spans only, so each part's marks ride through
// it in the span's colour and are read back after.
export const withInlays = (
  parts: readonly Part[],
  hints: readonly InlayHint[],
  rawLine: string | undefined,
): Part[] => {
  if (hints.length === 0) {
    return [...parts]
  }

  const placed = applyInlays(
    parts.map((part): Span => [
      `${part.color}\u0001${Number(part.isMarked)}${Number(part.isFound)}${Number(part.isFaded)}`,
      part.text,
    ]),
    hints,
    rawLine,
  )

  return placed.spans.map(([color, text], at) => {
    const [own = '', marks = '000'] = color.split('\u0001')

    return placed.isHint[at] === true
      ? { color: INLAY_COLOR, text, isMarked: false, isFound: false, isFaded: false, isHint: true }
      : {
          color: own,
          text,
          isMarked: marks[0] === '1',
          isFound: marks[1] === '1',
          isFaded: marks[2] === '1',
          isHint: false,
        }
  })
}

// Splits a line's spans where a diagnostic's columns start and end, so the
// range can be underlined, and where a search's matches do (`found`), so they
// can be lit. Columns are 1-based, `to` exclusive.
export const markSpans = (
  spans: readonly Span[],
  ranges: readonly (readonly [from: number, to: number])[],
  found: readonly (readonly [from: number, to: number])[] = [],
  // Code the checkers say is never used, which is drawn faded.
  faded: readonly (readonly [from: number, to: number])[] = [],
): Part[] => {
  const parts: Part[] = []
  let col = 1

  for (const [color, text] of spans) {
    const cuts = new Set([0, text.length])

    for (const range of [...ranges, ...found, ...faded]) {
      for (const edge of [range[0] - col, range[1] - col]) {
        if (edge > 0 && edge < text.length) {
          cuts.add(edge)
        }
      }
    }

    const edges = [...cuts].sort((a, b) => a - b)

    edges.slice(0, -1).forEach((from, at) => {
      const start = col + from

      parts.push({
        color,
        text: text.slice(from, edges[at + 1]),
        isMarked: ranges.some(range => start >= range[0] && start < range[1]),
        isFound: found.some(range => start >= range[0] && start < range[1]),
        isFaded: faded.some(range => start >= range[0] && start < range[1]),
        isHint: false,
      })
    })
    col += text.length
  }

  return parts
}

files.hooks/tree.ts:
// The file tree: paths as rows of folders and files, which of them a closed
// folder hides, and the icon a file wears wherever it is named.

// A folder holding more files than this starts closed in the tree.
const BIG_FOLDER = 40

export type TreeRow = {
  kind: 'dir' | 'file'
  path: string
  name: string
  depth: number
  size: number
}

type TreeNode = { dirs: Map<string, TreeNode>; files: string[]; size: number }

// The paths as a folder tree, in drawing order: folders before files, and a
// chain of folders that each hold only one folder drawn as one row (a/b/c).
export const buildTree = (paths: readonly string[]): TreeRow[] => {
  const root: TreeNode = { dirs: new Map(), files: [], size: 0 }

  for (const path of paths) {
    let node = root

    for (const part of path.split('/').slice(0, -1)) {
      const child = node.dirs.get(part) ?? { dirs: new Map(), files: [], size: 0 }
      node.dirs.set(part, child)
      child.size += 1
      node = child
    }

    node.files.push(path)
  }

  const rows: TreeRow[] = []

  const walk = (node: TreeNode, prefix: string, depth: number): void => {
    for (const [first, child] of [...node.dirs].sort((a, b) => a[0].localeCompare(b[0]))) {
      let name = first
      let last = child

      while (last.files.length === 0 && last.dirs.size === 1) {
        const [only] = [...last.dirs]

        if (only === undefined) {
          break
        }

        name += `/${only[0]}`
        last = only[1]
      }

      rows.push({ kind: 'dir', path: prefix + name, name, depth, size: last.size })
      walk(last, `${prefix}${name}/`, depth + 1)
    }

    for (const path of [...node.files].sort()) {
      rows.push({ kind: 'file', path, name: path.slice(prefix.length), depth, size: 1 })
    }
  }

  walk(root, '', 0)

  return rows
}

// The rows left once closed folders hide what is under them. A big folder
// starts closed and the rest open, or every folder starts closed (`isShut`,
// for a tree of the whole repo); `toggled` flips a folder from its default.
export const visibleTree = (
  rows: readonly TreeRow[],
  toggled: readonly string[],
  isShut = false,
): { row: TreeRow; isClosed: boolean }[] => {
  const shown: { row: TreeRow; isClosed: boolean }[] = []
  let hidden: string | undefined

  for (const row of rows) {
    if (hidden !== undefined && row.path.startsWith(hidden)) {
      continue
    }

    const isClosed =
      row.kind === 'dir' && (isShut || row.size > BIG_FOLDER) !== toggled.includes(row.path)

    hidden = isClosed ? `${row.path}/` : undefined
    shown.push({ row, isClosed })
  }

  return shown
}

// The file-type glyphs and their colours are the kit's, shared with the parked
// and ledger mods.
export { iconOf } from './kit/icons'
export type { Icon } from './kit/icons'

